// ✅ V00330: REGISTRO AUTOMÁTICO del Historial de Cambios.
//   Este archivo viaja CON el código: cada entrega de versión añade aquí su
//   entrada, así el módulo "Historial de Cambios" se actualiza SOLO al
//   publicar — sin capturar nada a mano. Las entradas manuales (Firestore)
//   se combinan con estas; si una versión se registra a mano, la manual manda.
//   Formato de fecha: aaaa-mm-dd. La hora es opcional.

export interface CambioApp {
  fecha: string;
  hora?: string;
  version: string;
  titulo: string;
  resumen: string;   // explicación cotidiana (la que se copia para WhatsApp)
  detalle?: string;  // detalle técnico opcional
}

export const CAMBIOS_APP: CambioApp[] = [
  { fecha: '2026-10-30', version: 'V00531', titulo: 'Facturación: "Ver documento" abre la factura en otra pestaña · "Editar factura" en la Ficha', resumen: 'En la Ficha de Factura, "Ver documento" abre la factura (el PDF; si no hay, la imagen) en otra pestaña del navegador. Para agregar, reemplazar o quitar documentos está el botón "Agregar o cambiar" (la ventana de siempre). Igual en Proveedores. La Ficha de Clientes tiene arriba el botón "✎ Editar factura", que abre Editar factura (número, fecha, status, cliente, total, documentos y sus operaciones) sin cerrar la Ficha.', detalle: 'TarjetaDocumentoFactura: enlace target=_blank al documentoPrincipal (documentosFactura.ts); los guardados en base64 se abren como blob (urlParaPestana en adjuntos.ts). fcd-btn-editar-ficha → abrirEditarFactura.' },
  { fecha: '2026-10-30', version: 'V00530', titulo: 'Facturación: el XML de la factura se puede subir en sus documentos · Corregir se ordena por columna · barra horizontal siempre a la vista', resumen: 'Subir el XML (CFDI) de una factura no funcionaba en Subir documentos / Documentos de la factura, ni en los archivos de Generar factura y Editar factura (Clientes y Proveedores): solo aceptaban PDF o imagen, y el XML ni siquiera aparecía para elegirlo. Ahora aceptan PDF, XML o imagen (la revisión del documento ya sabía leer el XML). En Subir PDF y XML, un XML que no se pueda cotejar sale como problema de ese archivo en lugar de trabar la ventana. En Corregir, clic en el nombre de una columna ordena de menor a mayor; otro clic, de mayor a menor; otro, como estaba. La barra para moverse a los lados queda siempre abajo de la pantalla mientras se ve la tabla (antes había que bajar hasta el final).', detalle: 'TiposAdjunto "factura" (PDF, imagen, XML) en adjuntos.ts; DocumentosFacturaModal y los Archivos de Generar/Editar factura. ordenCorregir.ts (siguienteOrden, ordenarFilasCorregir). ScrollHorizontalFijo (shared/components): barra sticky sincronizada.' },
  { fecha: '2026-10-30', version: 'V00529', titulo: 'Facturación de Clientes: "Actualizar factura" muestra lo que quedó en el servidor (y dice por qué si no cambió nada) · más rápido', resumen: 'Caso I8650: el botón decía "La factura ya estaba al día" y la Ficha y la tabla seguían igual. La Ficha comparaba con una copia vieja de la factura (abierta desde Corregir, que es una foto de cuando se presionó Revisar), y en el servidor no había nada que cambiar; la pantalla no se ponía al día. Ahora: al abrir una factura desde Corregir se abre como está en ese momento; después de presionar Actualizar factura (o Actualizar en Editar factura) la Ficha, la lista y Corregir muestran lo que quedó en el servidor; y si no había nada que cambiar, el aviso dice por qué con los números del servidor (por ejemplo, "en el servidor la factura ya la tenía en $ 50.00" o "en el servidor la operación cobra $ 100.00: su último cambio todavía no está guardado"). Más rápido: la factura y sus operaciones se leen al mismo tiempo, presionar el botón ya no vuelve a pintar todo el módulo, guardar una factura ya no repite la revisión de Ref Cliente ni el cotejo de CFDI de todas las operaciones, y los catálogos que se abren en segundo plano esperan a que no estés haciendo clic.', detalle: 'sincronizarFacturaConOperaciones devuelve la factura y sus operaciones del servidor (idsEsperados en paralelo) y diferenciasConServidor; ActualizarFacturaFicha (estado propio); opIndex con useValorEstable; Corregir abre grupoDeFactura de la lista viva y se recalcula tras Actualizar; precalentarCatalogos espera 2 s sin clics.' },
  { fecha: '2026-10-30', version: 'V00528', titulo: 'Facturación de Clientes: "Actualizar factura" en la Ficha (sin entrar a Editar factura) · las operaciones abren más rápido', resumen: 'En la Ficha de Factura, cuando una operación tiene otro total hoy (por ejemplo, la I8650: TR-231026-030 guardó $100 y hoy cobra $50) o la factura no guardó lo que cobró cada operación, el aviso trae el botón "Actualizar factura": la pone al día ahí mismo, sin entrar a Editar factura, y antes de presionarlo dice qué pasa con el total (si no cambia porque ya lo incluía, o de cuánto a cuánto pasa). Es la misma regla del Actualizar de Editar factura. Las operaciones abren más rápido desde Facturación de Clientes: con las facturas ya en pantalla, los catálogos del formulario de operación se van abriendo en segundo plano (como en Operaciones Activas), así el primer ✎ Editar de la sesión ya no espera ni se traba mientras llegan; y al pasar el mouse por ✎ Editar la operación se empieza a leer antes del clic.', detalle: 'services/actualizarFactura.ts (planActualizarFactura, aplicarActualizarFactura, textoActualizar): una regla para Editar factura y la Ficha. operaciones/services/lecturaOperacion.ts (precargarOperacion, leerOperacionParaEditar, 8 s, una vez). precalentarCatalogosFormulario al cargar las facturas.' },
  { fecha: '2026-10-30', version: 'V00527', titulo: 'Facturación de Clientes: cada operación cuenta con su TOTAL (con cargos adicionales), no con el subtotal', resumen: 'Caso de la factura 39802: la operación TR-241026-005 tiene subtotal $140 y $250 de cargos adicionales (total $390), y la factura dice $390, pero la Ficha mostraba la referencia en $140: la factura guardó el subtotal antes de que se capturaran los cargos. Ahora la Ficha muestra $140 tachado → hoy $390 con un aviso, y en Editar factura, Actualizar guarda el total de hoy de cada operación SIN sumarlo dos veces: si el total de la factura ya lo incluía, no cambia (antes lo hubiera subido a $640). Si la factura no cuadraba con sus operaciones, se guardan los importes de hoy y el total no se toca. Completar importes (Corregir) también pone al día, en bloque y con los mismos tres pasos, las facturas que guardaron importes viejos y con el total de hoy de sus operaciones cuadran; las demás se quedan para revisarlas a mano. En Datos para la Factura y en el Reporte por facturar el importe dice "Total (sin IVA)" en lugar de "Subtotal": es el total de cada operación con sus cargos adicionales.', detalle: 'sincronizarFactura.ts: ModoSincronizar (yaIncluido / diferencia / soloImportes). completarImportes.ts: reemplaza renglones viejos solo si con lo de hoy cuadran. Ficha: useOperacionesDeFactura + opsDesfasadas.' },
  { fecha: '2026-10-30', version: 'V00526', titulo: 'Facturación de Clientes: Reporte por facturar (Excel para imprimir)', resumen: 'En Asignar Operaciones hay un botón nuevo, Reporte por facturar. Descarga un Excel listo para imprimir con lo pendiente por facturar (todo, o lo que dejes con los Filtros: fechas, cliente, tipo o búsqueda): una fila por referencia, agrupado por cliente, con Ref. Roelca, Ref. Cliente, fecha, caja, servicio, la columna Datos para la Factura (la leyenda que se copia al SIT o a QuickBooks), la moneda del cliente, el importe ya convertido y una columna vacía para anotar el # de factura; al final de cada cliente su suma, y el total general en dólares y en pesos. La leyenda ahora incluye el nombre del ejecutivo que pidió el servicio (de Obs. Ejecutivo, sin el correo; si es una nota y no un nombre, no se pone). Además, el botón Datos para el SIT ahora se llama Datos para la Factura (sirve igual para QuickBooks) y Subir XML se llama Subir PDF y XML.', detalle: 'reportePorFacturar.ts (armarReporte puro + libroReportePorFacturar con ExcelJS, cargado al descargar; descarga con descargarBuffer). ejecutivoSit en datosParaSit.ts. Código recibido como "V00525" de otra sesión, integrado y mejorado.' },
  { fecha: '2026-10-29', version: 'V00525', titulo: 'Facturación de Clientes: Actualizar guarda lo que cobra cada operación en las facturas que no lo tenían', resumen: 'En las facturas que no guardaron lo que cobró cada operación (por eso en la Ficha salen en $0.00, como la 35539), Editar factura ahora muestra lo que cobra hoy cada operación y Actualizar lo guarda en la factura. El total no cambia. Si no suman el total, la factura queda en Corregir con la diferencia. La Ficha avisa de estas facturas con un enlace a Editar factura. Es lo mismo que Completar importes, para una factura a la vez.', detalle: 'Editar factura usa planCompletarImportes / completarImportes (V00524) con los documentos de la factura; no con dineroPorServidor ni al cancelarla.' },
  { fecha: '2026-10-29', version: 'V00524', titulo: 'Facturación de Clientes: Completar importes en la pestaña Corregir', resumen: 'En Facturación de Clientes → Corregir hay un botón nuevo, Completar importes, para las facturas que no guardaron lo que cobró cada operación (sobre todo las que vienen de AppSheet). A cada una le guarda su desglose con lo que cobra hoy cada operación, SIN cambiar el total: si la factura no tenía su total guardado, se guarda el mismo que ya muestra. Va en tres pasos que no se pueden saltar: 1) descargar la prueba en Excel (qué se completa, lo que cobra hoy cada referencia, cuánto suman y si cuadran con el total; y las que no se pueden, con su motivo), 2) descargar el respaldo, 3) escribir APLICAR. Las que cuadran salen de Corregir; las demás pasan a "Sus operaciones no suman el total" con la diferencia por referencia. No se completan (quedan para revisarlas a mano): las que solo guardaron las referencias, las que tienen una operación que no existe o que está en otra factura, sin moneda o sin total. Queda en la bitácora.', detalle: 'completarImportes.ts: renglonFactura por operación, comprobación de que el total no cambia, transacciones de 20 facturas que releen factura y operaciones. No con dineroPorServidor.' },
  { fecha: '2026-10-29', version: 'V00523', titulo: 'Facturación de Clientes: Corregir muestra las referencias con sus montos y abre la factura con un clic', resumen: 'En la pestaña Corregir, un clic en la factura (en cualquier parte de la fila) abre su Ficha. Hay una columna nueva, Referencias: cada referencia con lo que cobra en la factura y, si hoy la operación cobra otra cosa (o la factura no lo guardó), lo que cobra hoy (por ejemplo: $ 120.00 tachado → hoy $ 150.00). En el motivo dice si, con el costo de hoy de sus operaciones, la factura cuadraría ("Con el costo de hoy, cuadra.") o cuánto sumarían. Para eso se leen solo las operaciones de las facturas que se ven en pantalla. Nada cambia: ni los totales ni las operaciones.', detalle: 'useOperacionesPorId (porIds, una vez cada operación, solo filas visibles), sumaConHoy en cuadreFactura.ts, importeEn (cotejoCfdi).' },
  { fecha: '2026-10-29', version: 'V00522', titulo: 'Facturación de Clientes: importe de cada referencia · pestaña Corregir · sin Corregir monedas y montos', resumen: 'En Facturación de Clientes → Historial, la columna Referencias muestra al lado de cada referencia lo que cobra en la factura. Si las referencias no suman el total de la factura, aparece un aviso (Suman $…, o Sin importes si la factura no guardó lo que cobró cada operación). Hay una pestaña nueva, Corregir, con todas las facturas cuya suma de operaciones no es igual a su total: invoice, fecha, cliente, moneda, suma de operaciones, total, diferencia y por qué (no suman el total, la diferencia es el IVA de 16%, no guardó lo que cobró cada operación, o no tiene operaciones), con filtros por motivo. El botón Revisar las busca entre todas las facturas y NO cambia ningún total. Ver factura abre su Ficha para corregirla. Las canceladas no se revisan. Se quitó el botón Corregir monedas y montos de Facturación de Clientes.', detalle: 'cuadreFactura.ts (puro, en centavos; IVA 16% de las facturas viejas). Cero lecturas: usa las facturas que ya están en pantalla. Proveedores conserva Corregir monedas y montos.' },
  { fecha: '2026-10-29', version: 'V00521', titulo: 'Facturación de Clientes: Ops. Facturadas muestra las operaciones', resumen: 'En Facturación de Clientes → Historial, la tarjeta Ops. Facturadas ahora lista las OPERACIONES facturadas y no las facturas: referencia, caja, invoice, fecha, cliente, moneda y lo que cobra cada una en su factura. Sigue los filtros del historial: si buscas una factura (por ejemplo A5510) salen solo sus operaciones; sin filtro, todas las facturadas. Con un clic en una operación se abre su detalle (con ✎ Editar operación); al cerrarlo vuelves a la lista. Se muestran de 300 en 300 (botón Mostrar más) y Descargar Excel trae todas, una fila por operación. En las facturas viejas que no guardaron lo que cobró cada operación, el importe sale como —. Las otras tarjetas siguen listando facturas.', detalle: 'filasOpsDeTarjeta: de los renglones de cada factura filtrada (cero lecturas); el Excel resuelve las referencias que falten (resolverOpsParaExport).' },
  { fecha: '2026-10-29', version: 'V00520', titulo: 'Facturación de Clientes: abrir la factura desde Facturas Listadas · editar sus operaciones desde la factura · Editar factura más ancha y con Actualizar', resumen: 'En Facturación de Clientes → Historial, en la ventana de Facturas Listadas (y en las otras tarjetas) cada factura se puede abrir con un clic: se abre su Ficha y al cerrarla vuelves a la lista. En la Ficha, cada operación tiene ✎ Editar, que abre el formulario completo de la operación (también sigue el Editar del detalle). Editar factura es más ancha y abajo muestra las operaciones de la factura, cada una con lo que cobra y su ✎ Editar. Nada se guarda hasta presionar Actualizar, que solo se activa cuando cambias algo. Si cambias el costo de una operación, Editar factura lo marca ("En la factura 70.00 → hoy 75.00") y dice cómo queda el total; al presionar Actualizar la factura toma el costo de hoy: el renglón de esa operación y el total suben o bajan la misma diferencia (un total que ya traía IVA lo conserva), con su saldo. No puede quedar por debajo de lo pagado. Queda en la bitácora.', detalle: 'sincronizarFactura.ts (transacción que relee factura y operaciones), useOperacionesDeFactura (porIds + operacionesBus), OperacionesFacturaEdicion. No con dineroPorServidor, folios con varios registros ni facturas sin lo que cobró cada operación. Solo Clientes.' },
  { fecha: '2026-10-29', version: 'V00519', titulo: 'Facturación: el documento se compara con el total y la diferencia va a costos adicionales · cliente y monto fijos en Editar factura', resumen: 'Al revisar el PDF o XML de una factura (al subirlo o con Analizar documento), el monto de la factura se compara con el TOTAL del documento; si la factura de la app no lleva los impuestos y coincide con el subtotal, también está bien. También se leen las referencias viejas como TR46028-05. Si no coincide, en la Ficha de Factura aparece Poner la diferencia en costos adicionales: escribes cuánto va a cada operación (ya viene puesto en la que no cuadra) y la observación; la app muestra cómo quedan los costos de cada operación y el total de la factura, y al confirmar suma la diferencia a los costos adicionales de esas operaciones, les pone la observación en Observaciones de costos adicionales, actualiza su Por Cobrar y el total de la factura (y su saldo). En Editar factura (Clientes y Proveedores) ya no se puede cambiar el cliente o el proveedor ni el monto: salen de las operaciones; para cambiarlos, se cambian en cada operación.', detalle: 'documentoFactura.ts (monto contra total o subtotal, diferencia y diferencias por operación, costos con impuestos), leerCfdi.ts (referencias viejas, esRefOperacion), diferenciaEnCargos.ts (plan puro con pruebas + una transacción que relee factura y operaciones; no con dineroPorServidor), DiferenciaEnCargos en RevisionDocumentosGuardados, Editar factura sin selector ni total editable. CAMBIOS-V00519.md.' },
  { fecha: '2026-10-29', version: 'V00518', titulo: 'Revisión de datos: confirmar como correctas las canceladas con monto (D6)', resumen: 'En Operaciones → Revisión de datos → D6 (Canceladas que conservan su monto), cada operación tiene un botón ✓ Está bien: si ya la revisaste y de verdad se canceló, la confirmas y sale de la lista (con Deshacer por si te equivocas). También está Confirmar todas como correctas, con los mismos tres pasos que F1: prueba en Excel, respaldo y escribir APLICAR. No cambia el status ni los montos: solo la marca como revisada. Si después cambia su monto, vuelve a aparecer. Arriba dice cuántas están confirmadas.', detalle: 'revisionDatos.ts: detalleD6, confirmacionDe, GRUPOS_CONFIRMABLES y confirmadas; confirmarRevision.ts (una con updateDoc revisionOk.D6, Deshacer con deleteField, todas en transacciones de 100 que releen la operación); ConfirmarCorrectas en RevisionDatosModal; aplicarConfirmacionesLocales. CAMBIOS-V00518.md.' },
  { fecha: '2026-10-29', version: 'V00517', titulo: 'Revisión de datos: corregir el status de las operaciones de D3', resumen: 'En Operaciones → Revisión de datos, el grupo D3 (Sin status) tiene ahora la corrección Corregir status. Sirve para las operaciones cuyo status está guardado con otro nombre que el del catálogo: escrito con otros espacios o mayúsculas, o con un nombre viejo (por ejemplo "3. Documentado" cuando en el catálogo ya se llama "3. Documentado (Asignado)"). A cada una se le pone el status del catálogo que le corresponde, igual que los botones de status. Va en los mismos tres pasos que F1: descargar la prueba en Excel (dice qué status se le pondría a cada una y cómo se encontró), descargar el respaldo y escribir APLICAR. Las que no se parecen a ningún status, o se parecen a varios, no se tocan: se corrigen a mano. Al terminar salen de la lista y queda en la bitácora.', detalle: 'corregirStatusD3.ts (búsqueda pura con pruebas: mismo nombre tolerante, nombre anterior, mismo número; transacciones de 100 que releen la operación y el status del catálogo), CorregirStatusD3 en RevisionDatosModal, revisionDatos.ts entrega statusD3. Escribe status (id del catálogo), statusNombre y statusCorregidoPorRevision. CAMBIOS-V00517.md.' },
  { fecha: '2026-10-29', version: 'V00516', titulo: 'Facturación de Clientes: Analizar el documento de una factura ya subida', resumen: 'En la Ficha de Factura de Facturación de Clientes, la tarjeta del documento tiene un botón nuevo, Analizar documento. Descarga el PDF o XML que ya está subido y lo compara con lo que dice la factura en la app: número de factura o invoice, cliente, moneda, las operaciones (referencias), el costo de cada una y el subtotal. Debajo dice si coincide o qué no coincide, igual que al subirlo ("El costo no concuerda", "Ese subtotal no concuerda con la factura", "Esas no son las operaciones…"). Sirve para revisar las facturas que se subieron antes. Las imágenes no se pueden leer: solo PDF y XML. Solo revisa: no cambia nada.', detalle: 'leerDocumentoGuardado (fetch de la URL guardada, tipo por contenido %PDF / <?xml, caché por URL sin guardar fallos), RevisionDocumentosGuardados, DocumentoFichaCliente (tarjeta + análisis, key por factura), botón opcional en TarjetaDocumentoFactura. Necesita CORS del bucket si no está puesto (cors.json, CAMBIOS-V00516.md).' },
  { fecha: '2026-10-29', version: 'V00515', titulo: 'Facturación: tarjetas al lado del título y tabla sin scroll propio', resumen: 'En Facturación de Clientes y de Proveedores, las tarjetas de resumen ya no ocupan un renglón propio: van al lado del título, más chicas, y cambian según la pestaña (en Asignar Operaciones: en espera, ya facturadas y total; en Historial y Pagadas: facturas listadas, operaciones facturadas y totales en dólares y pesos; las de Clientes siguen abriendo su detalle). Así la tabla sube. La tabla ya no tiene su propia barra para bajar: crece con sus filas y se baja con la barra de la ventana. La barra para moverse a los lados sigue al final de la tabla (o Shift + rueda del mouse). Como la tabla ya no se desplaza sola, sus encabezados ya no se quedan fijos arriba al bajar. En teléfono las tarjetas van debajo del título.', detalle: 'FacturacionClientesDashboard / FacturacionProveedoresDashboard: los bloques de tarjetas pasan a .fcd-encabezado / .fpd-encabezado (flex con el h1), condicionados por la pestaña; estilos compactos bajo ese contenedor (fcd-x69 y fpd-x65 también son el contador de seleccionadas). .fcd-x82 / .fpd-x78 sin max-height ni overflow-y. CAMBIOS-V00515.md.' },
  { fecha: '2026-10-29', version: 'V00514', titulo: 'Facturación de Clientes: el PDF / XML de la factura se revisa al subirlo', resumen: 'Al subir el documento de una factura (en Generar Factura o en Documentos de una factura ya registrada), la app lo lee y lo compara con la factura: número de factura o invoice, cliente, moneda, las operaciones (referencias) y el costo de cada una, y el subtotal. Lee los PDF del SIT (CFDI, en pesos o dólares) y los Invoice de Roelca Inc, y también el XML. Debajo de los archivos dice si el documento coincide o qué no coincide: "El número no es el mismo", "El cliente no es el mismo", "Esas no son las operaciones que van en esa factura", "El costo no concuerda", "Ese subtotal no concuerda con la factura". Compara el subtotal (los impuestos los controla el SIT). Solo avisa: no impide guardar.', detalle: 'leerFacturaPdf.ts (puro, con pruebas sobre el texto real de 5 PDF), documentoFactura.ts (comparación pura, misma regla de dinero que Generar Factura), textoPdf.ts (pdfjs-dist 6.4.299, se carga solo al revisar un PDF), leerDocumentoFactura.ts, RevisionDocumentosFactura en Generar Factura y DocumentosFacturaModal. Dependencia nueva: npm install. CAMBIOS-V00514.md.' },
  { fecha: '2026-10-29', version: 'V00513', titulo: 'Facturación de Clientes: Subir XML y PDF de facturas fiscales · Datos para el SIT', resumen: 'En Facturación de Clientes → Asignar Operaciones hay dos botones nuevos. Datos para el SIT: con las operaciones seleccionadas de un cliente muestra, por cada una, la descripción lista para el SIT (referencia, fecha, caja, Ref Cliente y, si se convirtió de moneda, el TC de la operación) y el importe ya convertido, con botones para copiar y el subtotal; son subtotales (el IVA y las retenciones los calcula el SIT) y no guarda nada. Subir XML: arrastras juntos el PDF y el XML de cada factura del SIT (hasta 60 por carga) y la app revisa cada una contra las operaciones por facturar: que el cliente (RFC) sea el de las operaciones, la moneda la del cliente, el folio no exista ya y el importe de cada referencia sea, al centavo, lo que cobra la app (y si el TC escrito no es el de la operación, lo dice). Las que cuadran tienen Registrar factura, que abre el Generar Factura de siempre ya llenado (operaciones, folio, fecha y los dos documentos: primero el PDF y luego el XML); solo falta confirmar. No se registra nada sin confirmar.', detalle: 'De otra sesión (sus V00511–V00513), unida aquí como una versión. leerCfdi.ts (DOMParser), cotejoCfdi.ts y datosParaSit.ts (puros, misma regla de dinero que Generar Factura), parearPdfXml.ts, SubirXmlModal + FilaCfdi, DatosSitModal. CAMBIOS-V00513.md.' },
  { fecha: '2026-10-29', version: 'V00512', titulo: 'Revisión de datos al día, con fechas y Cancelar · Observaciones de costos adicionales', resumen: 'Revisión de datos: tiene un rango de fechas (Desde / Hasta) para ver solo los errores de ese periodo; se aplica al momento, sin volver a leer, y se recuerda mientras no cierres sesión. Mientras revisa aparece el botón Cancelar revisión. Y la lista se mantiene al día: lo que abres desde la revisión y corriges (o cualquier operación que se guarde en la app) se vuelve a revisar solo y, si ya está bien, deja de aparecer; las que marcas en F1 salen de la lista al momento. En el formulario de operación (Por Cobrar), si los Cargos Adicionales son distintos de 0 aparece debajo la casilla Observaciones de costos adicionales.', detalle: 'revisionDatosLectura.ts (señal de cancelar, datos de la revisión en memoria, pendientes por abrir/guardar con operacionesBus, refrescarRevisionDatos con porIds/getDoc, aplicarCambiosLocales, rango de sesión), revisionDatos.ts filtrarPorFechas, RevisionDatosModal (rango, Cancelar, aviso Al día), marcarFacturadasF1 devuelve marcadasIds y congela el plan en la prueba, FormularioOperacion cargosAdicionalesNotas. CAMBIOS-V00512.md.' },
  { fecha: '2026-10-29', version: 'V00511', titulo: 'Falso: cobro al 50%, sueldo fijo y 3 galones · Nómina con el convenio', resumen: 'Cuando una operación pasa a Falso: se queda con el mismo convenio y se cobra al 50%, al cliente y al proveedor (ya no se cambia al convenio Falso); el sueldo del operador queda en $200 si es cruce de importación o exportación y en $150 si es movimiento (si no se puede clasificar, no se toca); y el diesel queda en 3 galones. Si la operación sale de Falso, todo regresa a como estaba. Lo que ya está facturado no se toca (avisa). Aplica de aquí en adelante: las que ya están en Falso se quedan como están. Al regresar el estatus, la ventana dice qué va a cambiar. En la ficha de la nómina, la tabla de operaciones pagadas muestra el convenio en lugar del cliente.', detalle: 'convenioFalso.ts (regla pura, cliente y proveedor al 50% con respaldo mitadFalso; compatibilidad con convenioAntesFalso de la V00509), convenioFalsoDatos.ts sin catálogos, utils/sueldoFalso.ts → ajusteOperadorPorStatus (sueldo fijo por movimiento + combustible 3 gal con combustibleCompleto), regresoStatus/regresoStatusDatos, FormularioOperacion, ReferenciasNominaDashboard (columna Convenio). CAMBIOS-V00511.md.' },
  { fecha: '2026-10-28', version: 'V00510', titulo: 'Revisión de datos: marcar como facturadas las operaciones de F1', resumen: 'En Operaciones → Revisión de datos, el grupo F1 (operaciones que ya están en una factura pero no tienen Invoice ni la marca de facturada) tiene ahora la corrección Marcar como facturadas. Va en tres pasos que no se pueden saltar: 1) descargar la prueba en Excel con lo que se le haría a cada operación, 2) descargar el respaldo con lo que tiene cada una hoy, 3) escribir APLICAR para autorizar y marcar. A cada operación se le pone el Invoice y la marca de facturada de la factura que la lista, igual que al facturar; las facturas N/A / No Aplica cuentan como activas. No cambia montos, facturas ni pagos. No se marcan las canceladas ni las que estén en dos facturas: se revisan a mano. Al terminar dice cuántas se marcaron y queda en la bitácora.', detalle: 'revisionDatos.ts entrega marcasF1 (id real de la factura). marcarFacturadasF1.ts (plan puro con pruebas, Excel de prueba, respaldo JSON, transacciones de 100 que releen operación y factura) + MarcarFacturadasF1 en RevisionDatosModal. Escribe facturaClienteId, facturaClienteInvoice, facturado y facturadoPorRevision. CAMBIOS-V00510.md.' },
  { fecha: '2026-10-28', version: 'V00509', titulo: 'Operaciones: convenio de Falso al marcar Falso · Empresas: botón Actualizar', resumen: '1) Cuando una operación pasa a un estatus Falso (desde Operaciones Activas, Canceladas, Regresar estatus en Completadas, Editar o Mis Operaciones), su convenio cambia solo al convenio Falso del mismo cliente: si el convenio era de exportación, al Falso de exportación; si era de importación, al Falso de importación. Cambian con él el monto y el Por Cobrar. Si la operación sale de Falso, regresa a su convenio de antes. No cambia una operación ya facturada al cliente, ni una que ya tiene convenio Falso. Si el cliente no tiene convenio Falso de ese tipo, la app lo avisa y deja el convenio como estaba. 2) En Empresas, el botón Recargar catálogos ahora es Actualizar: vuelve a contar las operaciones de cada empresa sin recargar la página (antes la Cantidad de Operaciones se quedaba vieja).', detalle: 'convenioFalso.ts (puro, con pruebas) + convenioFalsoDatos.ts (relee la operación y los convenios con fresco) en los 9 lugares que ya aplican el sueldo de Falso; Regresar estatus dentro de su transacción. Respaldo en convenioAntesFalso. Empresas: CLAVE_CONTEO_OPS sin caché al Actualizar, removeQueries usos, reintentarCatalogo. CAMBIOS-V00509.md.' },
  { fecha: '2026-10-28', version: 'V00508', titulo: 'Facturación: Remisión en cualquier status · Empresas: pasar operaciones a otra empresa', resumen: '1) En Facturación de Clientes y de Proveedores el botón Remisión se ve siempre, sin importar el status de la factura (antes se ocultaba con la factura Facturada). 2) En Empresas, en la pestaña Referencias de una empresa, ahora se pueden marcar operaciones y pasarlas a otra empresa con el botón Pasar a otra empresa. Se elige la empresa destino y el papel que cambia (por ejemplo Proveedor (Unidad)). Si alguna ya está facturada en ese papel, la ventana pregunta qué hacer: no pasarlas, pasarlas sin tocar su factura, o pasarlas con su factura y sus pagos (solo si todas las operaciones de la factura se pasan). Antes de pasar dice cuáles pasan y cuáles no, con el motivo, y pide confirmar. Solo cambia la empresa: montos, convenio y moneda se quedan. Queda en la bitácora.', detalle: 'Remisión: se quitó puedeGenerarRemision (V00481) de las dos pantallas. Pasar: pasarOperaciones.ts (puro, con pruebas) + pasarOperacionesEscritura.ts (runTransaction que relee cada documento; factura + operaciones + pagos en la misma transacción) + PasarOperacionesModal; casillas en Referencias. CAMBIOS-V00508.md.' },
  { fecha: '2026-10-28', version: 'V00507', titulo: 'Empresas: reporte de clientes y proveedores con dirección y operaciones', resumen: 'En Empresas hay un botón nuevo, Reporte. Descarga un Excel con todos los clientes y todos los proveedores, cada uno con su dirección (calle, número, colonia, municipio, estado, C.P. y país, y las otras direcciones que tenga) y cuántas operaciones tiene: cuántas de importación, cuántas de exportación y cuántas de otros (movimientos, en falso y sin clasificar). Clientes y proveedores van en hojas separadas; una empresa que es las dos cosas sale en las dos. La hoja Resumen trae los totales. Se puede elegir un periodo por fecha de servicio o dejarlo vacío para contar todas las operaciones. Las canceladas y las de prueba no cuentan. Solo lee: no cambia nada.', detalle: 'reporteEmpresas.ts (puro, con pruebas) + reporteEmpresasLectura.ts (leerOperacionesDelRango o recorrerOperaciones + catálogos abiertos) + excelReporteEmpresas.ts (ExcelJS: Resumen, Clientes, Proveedores) + ReporteEmpresasModal. La clasificación de Estadísticas pasó a operaciones/services/clasificacionOperacion.ts (misma regla). CAMBIOS-V00507.md.' },
  { fecha: '2026-10-28', version: 'V00506', titulo: 'Empresas: Tipo(s) de Empresa y Tipo de Factura con su nombre', resumen: 'En Empresas, el detalle y Editar empresa mostraban a veces el código en lugar del nombre en Tipo(s) de Empresa (por ejemplo "ca21ab07") y en Tipo de Factura. Pasaba con los registros que traen dos códigos (el de AppSheet y el de la base de datos). Ahora se reconoce cualquiera de los dos y se ve el nombre. Al guardar, cada empresa conserva los mismos códigos de siempre, para que los demás módulos la sigan encontrando. Además, Editar empresa ya no se recarga sola cuando alguien guarda otra empresa: antes se perdía lo que se estaba capturando.', detalle: 'shared/data/indiceCatalogo.ts (idsDeRegistro, diccionarioCatalogo, traductorCatalogo) en EmpresasDashboard y FormularioEmpresa; la carga de la empresa depende solo de initialData. CAMBIOS-V00506.md.' },
  { fecha: '2026-10-28', version: 'V00505', titulo: 'Operaciones: Revisión de datos (solo lectura)', resumen: 'En la barra de Operaciones hay un botón nuevo, Revisión de datos. Al presionar Revisar lee todas las operaciones (dice cuántas lleva) y las facturas de clientes, y lista los errores por grupo con su cantidad y prioridad: operaciones en dos o más facturas, operaciones que están en una factura pero no tienen Invoice ni la marca de facturada, referencias repetidas, Invoice que no existe en Facturas, moneda de cobro distinta a la de la empresa, montos que no cuadran, datos que faltan, facturas cuyo total no es la suma de sus operaciones (aparte las de centavos), canceladas con monto, terminadas sin facturar y operaciones sin status. Cada registro tiene un botón Abrir que lleva a su ficha, y botones a sus facturas o a la otra operación con la misma referencia. Todo sale también en un Excel. No cambia nada: las correcciones vienen en la siguiente versión.', detalle: 'revisionDatos.ts (puro, con pruebas) + revisionDatosLectura.ts (recorrerOperaciones + listener pagos:facturas_clientes) + RevisionDatosModal. C1–C5 del reporte confirmados (V00496/V00497); prueba nueva de descargarFacturas (C5). CAMBIOS-V00505.md.' },
  { fecha: '2026-10-27', version: 'V00504', titulo: 'Facturación de Clientes: Excel de todas las facturas', resumen: 'En Facturación de Clientes → Historial de Facturas → Exportar Excel, la ventana pregunta qué facturas llevar: "Las de la pantalla" (con los filtros de ahora, como antes) o "Todas las facturas": pagadas y sin pagar, con y sin fecha, de todos los clientes y status, sin filtros. El Excel trae una columna nueva, "Estado de pago" (Pagada, Parcial o Sin pagar), y los totales en dólares y en pesos por separado (sin canceladas). La fila TOTAL del final solo sale si todas son de la misma moneda: antes sumaba dólares con pesos.', detalle: 'alcanceExportFac + todasLasFilasFac (agruparFacturas sobre la lista en vivo), estadoPagoFila/filaPagada en gruposFactura.ts, filaTotal en exportarExcelProfesional. CAMBIOS-V00504.md.' },
  { fecha: '2026-10-27', version: 'V00503', titulo: 'Excel de operaciones: columna ok / error, Moneda Empresa y monedas de color', resumen: 'Los Excel de Operaciones y de Servicios Completados traen dos columnas nuevas al inicio. "Validación" dice ok o error, para filtrar el Excel; "Motivo" dice por qué es error. Cuenta como error: datos que faltan (cliente que paga, moneda de la empresa en Empresas, convenio, monto, moneda del convenio, moneda de cobro o el tipo de cambio cuando hace falta), Moneda Cobro distinta a la moneda de la empresa, y Dólares, Pesos o Conversión que no cuadran con la regla. La regla: convenio en dólares y cobro en dólares, el monto va en Dólares y la Conversión es el monto por el tipo de cambio; convenio en dólares y cobro en pesos, el monto por el tipo de cambio va en Pesos y en la Conversión; convenio en pesos y cobro en pesos, lo mismo en Pesos y en la Conversión; convenio en pesos y cobro en dólares, el monto entre el tipo de cambio va en Dólares y la Conversión es por el tipo de cambio. El motivo dice cuánto debería ser. Las canceladas no se revisan. Al lado de Moneda Cobro sale "Moneda Empresa", la moneda del cliente que paga en Empresas. Las monedas se pintan: Dólares en azul y Pesos en verde. El encabezado queda fijo y con los filtros puestos.', detalle: 'validacionExcel.ts (puro, con pruebas), monedasEmpresas.ts, excelOperaciones.ts con ExcelJS (colores, autoFilter, encabezado fijo). CAMBIOS-V00503.md.' },
  { fecha: '2026-10-27', version: 'V00502', titulo: 'Buscador en toda la app (barra de arriba, Ctrl+K)', resumen: 'La barra de búsqueda de arriba ahora busca en TODA la app, como la de QuickBooks: al escribir muestra las operaciones, facturas, pagos, empresas, convenios, empleados, unidades y remolques que coinciden, con su fecha, monto y estado. Al hacer clic (o Enter) se abre su detalle en su módulo: la ficha de la operación en Activas, Completadas o Canceladas, la ficha de la factura, el pago, el Detalle de Empresa, la ficha del convenio, etc. Sin importar mayúsculas ni acentos. Las operaciones se encuentran por el inicio de la referencia, de la ref. cliente o del remolque. Ctrl+K pone el cursor en el buscador desde cualquier pantalla; con la caja vacía muestra lo abierto hace poco. Donde la barra filtraba la pantalla, lo sigue haciendo.', detalle: 'shared/data/aperturas.ts (abrirRegistro + useAtenderApertura), features/buscador, BuscadorTopbar, gruposFactura compartido. CAMBIOS-V00502.md.' },
  { fecha: '2026-10-27', version: 'V00501', titulo: 'Excel: Año, Mes, Semana y Día al lado de la fecha de servicio', resumen: 'En los Excel de Operaciones, Servicios Completados y Servicios Cancelados, la fecha de servicio siempre lleva al lado Año, Mes, Semana y Día (por ejemplo: 2026, octubre, 44, lunes), en cualquier configuración, sin tener que marcarlas. La semana es la del año, de lunes a domingo, como en Estadísticas Operativas. También se corrigió Estadísticas Operativas: con el horario de verano cada lunes aparecía en la semana anterior; ahora el lunes empieza su semana.', detalle: 'desgloseFechaExcel + semanaDelAnio/partesDeFecha (shared/dominio/fechas.ts, en UTC). CAMBIOS-V00501.md.' },
  { fecha: '2026-10-27', version: 'V00500', titulo: 'Operaciones: el Excel trae todas las operaciones del rango, también las que vienen de AppSheet', resumen: 'El Excel de Operaciones de un rango largo traía solo unas cuantas operaciones (las capturadas en la app web): las que vienen de AppSheet tienen la fecha guardada en otro formato (26/10/2026) y la búsqueda por fecha no las encontraba. Ahora el Excel revisa todas las operaciones y se queda con las del rango, guarde la fecha como la guarde; la ventana dice cuántas lleva revisadas y cuántas van del rango. Tarda un poco más que antes. Además, la columna Status ya no sale "-" en las operaciones que no traían guardado el nombre de su status: se toma del catálogo.', detalle: 'Sin consultasCanonicas: recorrerOperaciones (todas, por id en 4 tramos, páginas de 2,000) + filtro por la fecha normalizada; con consultasCanonicas (tras la migración): rango por fechaServicioISO. conNombreDeStatus con catalogo_status_servicio. CAMBIOS-V00500.md.' },
  { fecha: '2026-10-27', version: 'V00499', titulo: 'Operaciones: el Excel descarga el rango completo, sin límite de cantidad', resumen: 'El botón Excel de Operaciones fallaba con rangos grandes (por ejemplo, de enero a octubre) con el aviso "Limit value in the structured query is over the maximum value of 10000": pedía demasiadas operaciones de una sola vez. Ahora las lee por partes hasta traer TODAS las del rango, sin importar cuántas sean, de cualquier status. Mientras lee, la ventana dice cuántas lleva y luego cuántas van en el Excel. La ventana ya no se ve corrida un instante al abrirse.', detalle: 'Páginas de 2,000 con cursor (todasLasOperacionesDelRango en shared/data/consultas.ts) sobre fechaServicio y fechaServicioISO, en paralelo; sin tope. Firestore rechaza limit > 10,000. Animación propia de la ventana (mxe-aparecer). CAMBIOS-V00499.md.' },
  { fecha: '2026-10-26', version: 'V00498', titulo: 'Operaciones: pestaña Reportes y botón Excel con todas las operaciones de un rango', resumen: 'Reportes ya no está en el menú lateral: ahora es una pestaña de Operaciones, junto a Activas, Completadas y Canceladas (con el mismo permiso de siempre). En la barra de pestañas de Operaciones hay un botón nuevo, Excel: descarga TODAS las operaciones de un rango de fechas de servicio, sin importar su status (activas, completadas, canceladas o en falso). Abre la misma ventana que el Excel de Servicios Completados: el rango de fechas, las configuraciones guardadas (Usar o borrar) y Nueva configuración, para elegir y ordenar las columnas. Las configuraciones son las mismas de Servicios Completados. El Excel de Servicios Completados sale igual que antes.', detalle: 'MODULOS_OPERACIONES + reportes; exportar/ModalExportarExcel.tsx (ventanas compartidas), exportar/ExcelOperaciones.tsx, services/excelOperaciones.ts (valores de cada columna, antes dentro de ServiciosCompletados), services/operacionesDelRangoExcel.ts (fechaServicio + fechaServicioISO del rango, sin filtro de status), services/configsExportExcel.ts.' },
  { fecha: '2026-10-26', version: 'V00497', titulo: 'Facturación: la lista de facturas se actualiza sola', resumen: 'Facturación de Clientes y de Proveedores ya no descarga todas las facturas al entrar: las recibe en vivo, con la misma conexión que usan Pagos y Estadísticas. Si otra persona (u otra computadora) crea, edita o borra una factura, se ve al momento: la operación sale de Pendientes sin recargar y no se vuelve a facturar por tener la lista de ayer. También gasta mucho menos: la primera vez se leen las facturas una sola vez para toda la app (antes cada módulo bajaba otra vez todas: más de 12,000 por colección, y Proveedores además las de clientes) y después solo llegan los cambios. El botón Refrescar ahora solo vuelve a leer las operaciones.', detalle: 'hooks/useFacturasEnVivo.ts con useColeccionViva(pagos:facturas_clientes / pagos:facturas_proveedores); el cruce de Proveedores con la de clientes; los parches locales de cada acción valen hasta la siguiente versión del listener.' },
  { fecha: '2026-10-26', version: 'V00496', titulo: 'Moneda de Empresas sin separar pagos de sus facturas, borrar duplicados en el servidor y Unir duplicados sin tope', resumen: 'El botón de moneda de Empresas ya no cambia la moneda de un pago aplicado a una factura emitida que se queda en otra moneda (antes podía quedar una factura en Pesos con su pago en Dólares): esos pagos se cuentan en el aviso como "Pagos sin tocar". Los pagos sin facturas, o cuyas facturas ya están en la moneda nueva, sí la toman. Pagos muestra, edita y cobra cada factura en la moneda de la factura (antes en la de la empresa), editar un pago ya no mezcla facturas de otra moneda y el saldo de cada cliente o proveedor se muestra por moneda. El aviso ya no dice que se corra Corregir monedas y montos para las facturas: las emitidas no cambian y, si alguna debe cambiar, se corrige en Facturación → Editar factura. Cuando el dinero lo maneje el servidor (bandera dineroPorServidor), borrar una factura duplicada ya no regresa a Pendientes las operaciones que siguen en otra factura no cancelada: se quedan ligadas a esa, igual que en la app. Unir duplicados de Pagos ya revisa todas las facturas (antes solo las primeras 12,000). Se agrega un script, con modo de prueba, para las facturas importadas de AppSheet que guardan sus operaciones como texto: las convierte en lista y marca sus operaciones como facturadas. Solo se corre con respaldo y autorización.', detalle: 'monedaPagos.ts + propagarAPagos (pagosSinTocar); destinoAlEliminar en shared/dominio/facturacion.ts (planEliminarFacturas y decidirLiberacion), otrasFacturasDe en la callable eliminarFactura; descargarFacturasComoVivas en Unir duplicados; functions/scripts/facturasTexto.ts (npm run facturas:texto) con su regla en facturasTextoPlan.ts; cambiosSaldoLegado en dominio/dinero.' },
  { fecha: '2026-10-26', version: 'V00495', titulo: 'Facturación: una factura emitida solo cambia de valor a mano, una por una', resumen: 'Regla nueva de Roelca: "una vez facturado, la única forma de cambiar el valor de la factura es manual, 1 x 1". Una factura emitida (todo status salvo No Facturado; sin status cuenta como Facturado) ya no cambia de valor sola: si se edita una operación que ya está en ella, la operación cambia pero la factura no (solo se copian el nombre del convenio y la Ref Cliente). Corregir monedas y montos de Facturación ya no las toca y las lista como "Ya facturada"; el botón de moneda de Empresas tampoco les cambia la moneda y dice cuántas dejó igual; Corregir monedas de Operaciones ya no corrige las operaciones facturadas, las lista para revisarlas. Para cambiar el valor de una factura emitida: Facturación → Editar factura (o Recalcular montos en Pagos, una factura a la vez). Las facturas en borrador (No Facturado) siguen a sus operaciones como antes. El aviso amarillo del formulario de la operación lo explica.', detalle: 'valorCongelado (shared/dominio/cascadaFacturas.ts) en operacionEscrita (relacional-v1.9), MOTIVO_FACTURADA en corregirFacturas.ts, facturasSinTocar en propagarMoneda.ts, MOTIVO_FACTURADA_OP en corregirMonedaConvenio.ts.' },
  { fecha: '2026-10-26', version: 'V00494', titulo: 'Facturación: las facturadas ya no vuelven a Pendientes y los importes facturados no cambian solos', resumen: 'Facturación ahora carga TODAS las facturas: antes solo las primeras 12,000 y, con cada factura nueva, otra quedaba fuera de la lista; sus operaciones (sobre todo las que llegaron de AppSheet sin la marca de facturada) volvían a "Pendientes" al día siguiente y se facturaban otra vez. Eliminar una factura (por ejemplo un duplicado) ya no regresa a Pendientes las operaciones que siguen en otra factura: se quedan ligadas a esa. Una operación ya facturada conserva sus importes: al abrirla ya no toma sola la moneda de la empresa ni el tipo de cambio del día, y el aviso amarillo lo dice; si alguien cambia un importe a mano, al guardar sí cambia la factura. El servidor ya no recalcula la factura cuando solo cambia el nombre del convenio, la Ref Cliente o el nombre de la moneda, y "Corregir monedas y montos" no toca los totales capturados a mano en Editar factura.', detalle: 'services/descargarFacturas.ts (sin tope de 12,000), planLiberarAlEliminar (facturarSeguro.ts), services/montosCongelados.ts en el formulario, tcParaOperacionGuardada sin cambios en facturadas, dominio/cascadaFacturas.ts en operacionEscrita (relacional-v1.8), MOTIVO_TOTAL_MANUAL en Corregir monedas y montos.' },
  { fecha: '2026-10-26', version: 'V00493', titulo: 'Estadísticas: los montos de Facturación salen de las facturas', resumen: 'En Estadísticas, el área Facturación (Desglose, Tendencia, Ventas, Utilidad y Promedios) ya toma el dinero del módulo de Facturación: las facturas de clientes con fecha de factura dentro del rango, sin canceladas, con el mismo total que el Historial de Facturación. Por eso los pesos y dólares cuadran con las tarjetas del Historial con las mismas fechas. Antes sumaba el Por Cobrar de cada operación por fecha de servicio, estuviera facturada o no, y una operación cobrada en dólares dentro de una factura en pesos se contaba en dólares. Lo que aún no tiene factura se muestra aparte como "Por facturar" (no se suma), igual que las operaciones facturadas cuyo proveedor todavía no manda su factura. El costo del proveedor sale de las facturas de proveedor de esas mismas operaciones. En Facturación, las tarjetas del Historial ya no suman las facturas canceladas (siguen en la lista con su aviso).', detalle: 'services/montosFacturados.ts (reparto del total de cada factura entre sus operaciones, al centavo), hooks/useMontosFacturados.ts (listener compartido de facturas; operaciones de otro periodo por id), normalizarFactura.ts único para Clientes, Proveedores y Estadísticas, sumaEnTotales en reglasFactura.' },
  { fecha: '2026-10-26', version: 'V00492', titulo: 'Tipo de Cambio: el T.C. del DOF se registra solo a las 5:00 a. m. (hora de Texas)', resumen: 'Todos los días a las 5:00 a. m., hora de Texas, la app registra sola en Tipo de Cambio el T.C. que publica ese día el Diario Oficial, tomado de Banxico: el FIX del día hábil bancario anterior (por ejemplo, el lunes 26 de octubre de 2026 es 18.6670, el FIX del viernes 23). Antes de guardarlo revisa que Banxico traiga justo el FIX de ese día; si no, no registra nada. Sábados, domingos y días inhábiles bancarios de México (calendario de la CNBV: Semana Santa, 16 de septiembre, 2 y 16 de noviembre, etc.) llevan el DOF del último día hábil, y los días festivos de la app el T.C. del día anterior, como al capturarlo a mano. Al registrar un viernes también crea el sábado y el domingo. Si alguien ya capturó el día, no lo cambia. Corre solo a las 5:00; si Banxico no responde, lo reintenta a los pocos minutos.', detalle: 'Cloud Function programada tipoCambioDofDiario (functions/src/tipoCambioDof.ts): 0 5 * * * America/Chicago, Banxico SieAPIRest SF43718, calendario bancario de México, plan puro con pruebas, transacción contra duplicados, token en Secret Manager (BANXICO_TOKEN).' },
  { fecha: '2026-10-26', version: 'V00491', titulo: 'Auditoría de la cadena: motivos de los problemas, importes en su moneda y editar con el formulario de Facturación', resumen: 'En Facturación de Clientes → Auditar cliente: 1) Al presionar la tarjeta de problemas se abre la lista de cada problema con su motivo, agrupada: en más de una factura, cancelada pero facturada, cambió después de facturarse, pagos que no cuadran con lo pagado, pagada de más, pagada de más por centavos (redondeo) y sin facturar. Al presionar uno se ve su camino. El Excel del reporte trae una hoja nueva, Problemas. 2) Cada tarjeta muestra el importe en la moneda en que se factura, con su color: una operación facturada en dólares muestra sus dólares (antes siempre la conversión en pesos), y las facturas y pagos su total, pagado y saldo en su moneda. La operación se compara con su factura en la moneda de la factura. 3) El lápiz de una factura abre el mismo formulario Editar Factura de Facturación (cliente, status, invoice, documentos, fecha, moneda y total); la auditoría queda detrás y regresa al cerrarlo.', detalle: 'AuditoriaCadenaCliente: problemasPorMotivo (MOTIVOS, centavos < $1), importe/monedaComparacion por operación, Importe en las tarjetas, onEditarFactura/detras; se quitó su editor propio de factura (escribía el total sin transacción). FacturacionClientesDashboard: prepararEdicionFactura + editarFacturaDesdeAuditoria.' },
  { fecha: '2026-10-26', version: 'V00490', titulo: 'Moneda de la empresa en operaciones, facturas y pagos', resumen: 'La moneda en que se cobra (o se paga) una operación ahora es siempre la de su empresa en Empresas: el cliente que paga o el proveedor de transporte. En el formulario de la operación, Facturado en ya no se puede cambiar: toma la moneda de la empresa (solo se elige a mano si la empresa no tiene moneda). El precio del convenio se queda en su moneda y se convierte con el tipo de cambio; por ejemplo, la LO-130126-6 de Caro-Kar tiene un precio de 130 dólares y se cobra en $2,328.30 pesos, el mismo monto de su factura. En Operaciones, el botón ahora se llama Corregir monedas: además de la moneda del convenio, pone Facturado en con la moneda de su empresa y recalcula Subtotal, Dólares, Pesos y Utilidad (la Conversión en pesos no cambia). El botón de moneda de Empresas hace lo mismo con las operaciones de esa empresa, ya recalcula sus montos y también corrige la moneda de sus pagos. La Auditoría de la cadena muestra la moneda en que se factura cada operación y, si el precio está en otra moneda, lo indica sin marcarlo como problema.', detalle: 'revisarOperacion (corregirMonedaConvenio.ts) con monedaEmpresa por lado (monedaDeEmpresa de Facturación) y lados opcionales; propagarMoneda corrige operaciones en transacción con esa regla y agrega pagos; FormularioOperacion fija facturadoEnCobrar/facturadoEnUnidad a la moneda de la empresa; Auditoría con monedaFacturaOperacion.' },
  { fecha: '2026-10-25', version: 'V00489', titulo: 'Facturación: una operación ya no se multiplica dos veces por el tipo de cambio', resumen: 'Algunas operaciones tienen "Facturado en" guardado de dos formas que se contradicen: el dato que usa el formulario dice una moneda y una copia vieja del nombre (de AppSheet) dice otra. La regla de cálculo tomaba las dos a la vez y, si el convenio era en dólares, multiplicaba el monto dos veces por el tipo de cambio. Así la D-6166 quedó en $810,473.63: la TR-110626-011 de $2,650 salía en $801,373.63 (2,650 × 17.3898 × 17.3898). Ahora la moneda de factura sale de un solo lugar, el mismo que usa el formulario, y Facturación muestra esa misma moneda en "Facturado En". Corregir monedas de convenio (Operaciones) también arregla los montos guardados de esas operaciones, y al corregir la conversión de una operación en el formulario su factura se actualiza. Después hay que correr Corregir monedas y montos en Facturación.', detalle: 'monedaFacturaOperacion (dinero.ts): ID primero, el nombre copiado solo si el ID no se reconoce; espejo del servidor igual; textoFacturadoEn en los tableros; Corregir monedas de convenio revisa también "Facturado en" con dos monedas; la cascada de operacionEscrita incluye Subtotal/Dólares/Pesos/Conversión.' },
  { fecha: '2026-10-25', version: 'V00488', titulo: 'Facturación: el filtro de fechas del Historial ya incluye las facturas con la fecha guardada en otro formato', resumen: 'En el Historial de Facturas de Clientes y de Proveedores, al filtrar por fechas (Desde / Hasta) se quedaban fuera, sin aviso, las facturas con la fecha guardada en un formato que la app no reconocía: fechas de Firebase (Timestamp), números de Excel, años de dos dígitos (15/06/26) o meses con nombre (15 de junio de 2026). Por eso los reportes exportados con un rango de fechas salían con menos facturas. Ahora esas fechas se reconocen, se muestran bien en la tabla y entran en el filtro y en el Excel. Las facturas que de plano no tienen fecha siguen sin entrar en un rango de fechas, pero ahora un aviso dice cuántas son, para corregirlas en Editar factura.', detalle: 'parseFechaFactura (selectores.ts): Timestamp/Date/{seconds}, serial de Excel y epoch, Timestamp como texto, año de 2 dígitos, mes con nombre; fechaFacturaISO en los filtros de fechas (lista, conteo por status y por moneda); aviso sinFechaHist.' },
  { fecha: '2026-10-25', version: 'V00487', titulo: 'Operaciones: botón Corregir monedas de convenio', resumen: 'En Operaciones, a la derecha de las pestañas Activas, Completadas y Canceladas, hay un botón nuevo: Corregir monedas de convenio. Sirve para las operaciones que no tienen guardada la Moneda Convenio (Cliente o Proveedor). Primero revisa todas las operaciones sin cambiar nada y dice cuáles se corrigen, cuáles hay que revisar a mano y cuáles no tienen de dónde sacar la moneda. Al confirmar, a cada una le pone la moneda de su convenio (o la que dice su conversión guardada) y recalcula Subtotal, Dólares, Pesos, Conversión y Utilidad como lo hace el formulario. Por ejemplo, la LO-050626-002 pasa de un Subtotal de $115 a $1,988.21 pesos, lo mismo que su Conversión Final. Si el convenio y la conversión guardada dicen monedas distintas, la operación no se toca y sale en la lista para revisarla en el formulario. Después hay que correr Corregir monedas y montos en Facturación para que las facturas queden con esos montos.', detalle: 'corregirMonedaConvenio.ts (puro, con pruebas), corregirMonedaConvenioDatos.ts (recorrido por páginas de 500 y transacción por operación), CorregirMonedasConvenioModal; botón en la barra de Operaciones (PestanasModulo con acciones).' },
  { fecha: '2026-10-24', version: 'V00486', titulo: 'Facturación: operaciones sin moneda del convenio ya no se facturan con el monto en dólares como si fuera en pesos', resumen: 'Algunas operaciones no tienen guardada la Moneda Convenio (Cliente o Proveedor), sobre todo las que vienen de AppSheet. El formulario de la operación (Por Cobrar) las calculaba bien, por ejemplo un convenio de 115 dólares facturado en pesos daba $1,988.21. Pero Facturación las tomaba como si el convenio fuera en la misma moneda de la factura y ponía $115 pesos. Por eso clientes que facturan en pesos tenían facturas con montos en dólares y pagos que salían como pagados de más. Ahora, cuando falta la moneda del convenio, la app la deduce de la conversión que la operación ya tiene guardada, y Facturación da lo mismo que Por Cobrar. Para arreglar las facturas que ya están mal, hay que correr Corregir monedas y montos en Clientes y en Proveedores.', detalle: 'dinero.ts: monedaConvenioDeducida (conversión guardada ≈ convenio × TC → USD; ≈ convenio → MXN) en conversionOperacion; la misma regla en el espejo del servidor (relacional.ts). Requiere desplegar operacionEscrita.' },
  { fecha: '2026-10-24', version: 'V00485', titulo: 'Facturación de Clientes: el filtro de moneda del Historial ya cuenta y filtra', resumen: 'En Facturación de Clientes → Historial de Facturas → Filtros, Moneda de facturación decía $ Dólares (0) y $ Pesos (0), y al elegir una de las dos la lista quedaba vacía. Ahora cada botón dice cuántas facturas hay en esa moneda y al elegirlo se ven solo esas.', detalle: 'El filtro comparaba el nombre de la moneda (Dólares / Pesos) con el código (USD / MXN); ahora compara códigos (codigoMonedaFactura).' },
  { fecha: '2026-10-24', version: 'V00484', titulo: 'Referencias de la empresa: editar y Actualizar; Pagos: plantilla de facturas y tablas que se expanden', resumen: 'Empresas → Detalle de Empresa → Referencias: cada operación tiene un botón de lápiz que abre el formulario de edición de la operación (también en el Detalle de Operación, con Editar operación); al guardar, su renglón se actualiza solo. El botón Actualizar vuelve a leer operaciones, convenios, facturas y pagos sin quitar la vista: la sección, la búsqueda y la posición de la lista se quedan como estaban. Pagos: en Registrar pago y en Editar pago están Descargar plantilla y Cargar plantilla. La plantilla es un Excel con el número de factura y, opcional, el monto; al cargarla se marcan las transacciones pendientes que coinciden, con su saldo completo. El monto solo confirma: si no es igual al saldo abierto, esa factura no se marca. Las que no se marcan salen en una lista con el motivo: el monto no coincide, ya está pagada, es de otra empresa, ya está en el pago, no se encontró o está repetida. Las Transacciones pendientes, las facturas de Editar pago y la lista del Detalle del pago tienen el botón Expandir: la tabla ocupa casi toda la pantalla (en Registrar pago, con los totales abajo) y Contraer o Esc la regresa.', detalle: 'referenciasEmpresa.ts (lectura de la pestaña, Actualizar y relectura de una operación); plantillaFacturas.ts (puro, con pruebas) + plantillaFacturasExcel.ts; PlantillaFacturas.tsx; TablaExpandible.tsx.' },
  { fecha: '2026-10-24', version: 'V00483', titulo: 'Facturación: Corregir monedas y montos incluye las facturas con pagos, y la ficha muestra sus pagos', resumen: 'Corregir monedas y montos ahora corrige todas las facturas, tengan pagos o no (antes se saltaban las que ya tenían pagos). En las que tienen pagos, los pagos no se tocan: el saldo se recalcula con lo ya pagado (Parcial o Pagada). Si lo pagado pasa del total nuevo, la factura queda Pagada con saldo $0 y la lista la marca como pagada de más, con la diferencia, para revisarla en Pagos. La lista de la revisión trae la columna Pagado. Solo se siguen saltando las canceladas, las de empresas sin moneda y las que no tienen operaciones con importe. En la Ficha de Factura, si la factura tiene pagos, la ficha es más ancha y a la derecha aparecen sus pagos: total, pagado y saldo, y cada pago con su número, fecha, método, referencia y lo que aplicó a esta factura. Al hacer clic en un pago se abre Pagos con el detalle de ese pago (para quien tiene acceso a Pagos). En el teléfono los pagos van debajo del detalle y los datos de la ficha ya no se salen de la pantalla.', detalle: 'corregirFacturas.ts (plan sin pagos + saldo y statusPago con montoPagado; pagadoDeMas), pagosDeFactura.ts (índice de pagos por factura del listener que ya existía), PagosDeFactura.tsx, pagoPedido.ts (Facturación → Pagos abre ese pago).' },
  { fecha: '2026-10-24', version: 'V00482', titulo: 'Facturación: botón Corregir monedas y montos y una vista más sencilla', resumen: 'En el Historial de Facturas de Clientes y de Proveedores hay un botón nuevo, Corregir monedas y montos. Primero revisa todas las facturas sin cambiar nada y dice cuántas se corrigen, cuántas ya están bien y cuáles se saltan y por qué. Al confirmar, cada factura queda en la moneda de su cliente o proveedor en Empresas, con el total de sus operaciones: en Dólares la suma de Dólares (Cliente o Proveedor); en Pesos la Conversión Final. Se saltan las canceladas, las que ya tienen pagos aplicados (se listan para revisarlas en Pagos), las de empresas sin moneda y las que no tienen operaciones con importe. La moneda ya no se cambia a mano en Facturación. Se quitaron los botones Encabezado Remisión, Verificar y Sincronizar con Empresas. La vista es más sencilla: buscador y botones en la misma fila que Filtros, tarjetas más chicas, filas más bajas y, si una factura tiene más de 3 referencias, se ven 3 y +N (el resto en la ficha).', detalle: 'corregirFacturas.ts (planRecalcularFactura por factura + campo de moneda de su lado), corregirFacturasDatos.ts (transacción por factura; con dineroPorServidor la callable recalcularFactura), CorregirFacturasModal, AccionesHistorial; monedaDeEmpresa: manda empresa.moneda.' },
  { fecha: '2026-10-24', version: 'V00481', titulo: 'Facturación: Remisión, cancelación con reemplazo, moneda del cliente y colores por moneda', resumen: 'En Facturación de Clientes y de Proveedores: 1) Una factura Facturada ya no muestra Remisión ni Agregar referencia (en la ficha), ni el botón de Remisión en la tabla; si alguien lo intenta, la app no la genera. 2) Al pasar una factura a Cancelado (en la ficha, en Editar Factura o en Pagos) se pide una nota y el número de la factura que la reemplaza; sin las dos no se cancela. La ficha muestra la cancelación (la reemplaza, nota, cuándo y quién). Una factura nueva ya no se puede crear Cancelada. 3) La moneda de la factura es siempre la del cliente o proveedor en Empresas: en Editar Factura ya no se elige ni se quita, y si la empresa no tiene moneda no se puede facturar ni guardar. Si la factura estaba en otra moneda, la ficha y el editor lo avisan y el total sugerido pasa a la moneda correcta. 4) El importe de cada operación de la factura sale en su moneda: Dólares toma Dólares (Cliente) y Pesos toma Conversión Final (Ingreso). Total Facturado de la ficha y el total al generar la factura también van en esa moneda. 5) Los importes y la palabra Pesos van en verde y los de Dólares en azul (antes estaba al revés en tarjetas, filtros y columnas). 6) En el Detalle de Operación que se abre desde la ficha hay un botón Editar operación; la ficha queda detrás del formulario.', detalle: 'reglasFactura.ts (puro, con pruebas), statusFacturaDatos.ts; componentes Importe/NombreMoneda, AvisoMonedaFactura, CamposCancelacion, ModalCancelarFactura, CancelacionFicha; campos nuevos motivoCancelacion, facturaReemplazo, canceladaEn, canceladaPor (no son de dinero).' },
  { fecha: '2026-10-24', version: 'V00480', titulo: 'Facturación: clientes y proveedores en un solo lugar, con pestañas', resumen: 'En el menú ahora hay un solo apartado, Facturación (debajo de Análisis de Clientes), en lugar de Facturación dentro de Clientes y Facturación dentro de Proveedores. Arriba del módulo están las pestañas Clientes y Proveedores; cada una funciona igual que antes (sus filtros, búsquedas y fichas se conservan al cambiar de pestaña). Cada persona ve solo las pestañas que su rol tiene; con una sola, no aparece la barra. Los menús Clientes y Proveedores se quedan con Tarifario y Convenio. Las pestañas de Operaciones usan ahora la misma barra.', detalle: 'PestanasModulo (shared, pmo-) para Operaciones y Facturación; modulosFacturacion.ts con pestanaDeFacturacion; App.tsx: ítem Facturación y barra arriba de los dos MantenerVivo; etiqueta menu.facturaci_n.' },
  { fecha: '2026-10-23', version: 'V00479', titulo: 'Análisis de Clientes: quién crece, baja, dejó de operar o es nuevo', resumen: 'Módulo nuevo en el menú, debajo de Estadísticas: Análisis de Clientes, con las operaciones del año (sin canceladas). Resumen: totales, clientes por estado y Qué está cambiando, con los clientes de 20 o más operaciones que dejaron de operar, bajan, crecen o son nuevos, por Cliente Paga y por Cliente Mercancía. Cliente Paga y Cliente Mercancía: tabla con estado, operaciones, % del total, cambio de los últimos 3 meses, operaciones por semana de las últimas 4 semanas, día fuerte, pausa más larga y última operación, con buscador y filtro por estado; al elegir un cliente se ve su ficha (operaciones por trimestre, días que opera, importación, exportación, vacíos, Hazmat, en falso, sábados y operaciones por mes). Días y pausas: días con operación, días hábiles sin operar, pausa más larga, días sin operar y qué días de la semana trabaja cada cliente. Cada nombre abre sus operaciones, de la más reciente a la primera. Se puede ver el año actual o los dos anteriores. Las reglas de cada estado están en Cómo se clasifica cada cliente. Para verlo, el rol necesita el permiso Análisis de Clientes.', detalle: 'Ver CAMBIOS-V00479.md' },
  { fecha: '2026-10-23', version: 'V00478', titulo: 'Empresas: encontrar los duplicados por nombre y unirlos desde la misma ventana', resumen: 'El botón Duplicadas de Empresas ahora dice cuántos grupos hay y encuentra más casos: el mismo nombre aunque cambie la forma legal o los signos (Roelca Inc. = ROELCA; Tubería y Válvulas del Norte SA de CV = Tuberia y Valvulas Del Norte), nombres parecidos por una letra de más o de menos (Like Solutions Logisticss ≈ Like Solutions Logistics) o con una palabra de más, y el mismo RFC. Los nombres con números distintos (Planta 5 / Planta 6) no se juntan. La ventana tiene buscador y filtros (Mismo nombre, Parecidos, Mismo RFC); cada registro muestra cuántas operaciones tiene y Ver uso dice dónde aparece. Se marcan los que son la misma empresa y Unir conserva uno (por omisión, el que tiene más operaciones) y pasa a él todas las referencias de los demás. En la tabla, las empresas con posible duplicado llevan la etiqueta Posible duplicado, que abre su grupo.', detalle: 'Ver CAMBIOS-V00478.md' },
  { fecha: '2026-10-23', version: 'V00477', titulo: 'Operaciones: activas, completadas y canceladas en un solo lugar, con pestañas', resumen: 'En el menú ahora hay un solo apartado, Operaciones, en lugar de Operaciones Activas, Servicios Completados y Servicios Cancelados. Arriba del módulo están las pestañas Activas, Completadas y Canceladas; cada una funciona igual que antes (sus filtros, búsquedas y botones), y al cambiar de pestaña lo que ya se tenía abierto se conserva. Cada persona ve solo las pestañas que su rol tiene permitidas. El nombre del apartado se puede cambiar en Personalizar Etiquetas (Operaciones).', detalle: 'Ver CAMBIOS-V00477.md' },
  { fecha: '2026-10-22', version: 'V00476', titulo: 'Servicios Completados: regresar una operación completada o en Falso a otro estatus', resumen: 'En la ficha de una operación de Servicios Completados hay un botón nuevo, Regresar estatus. Abre una ventana con los estatus de su flujo (Reglas de Estatus), en orden; los que ya pasó dicen cuándo, y viene marcado el último por el que pasó antes de completarse o irse a Falso. Se elige el estatus y la fecha y hora del movimiento. Antes de guardar, la ventana dice qué va a pasar: si sale de Servicios Completados y vuelve a Operaciones Activas, cómo queda el sueldo del operador (al salir de Falso regresa al completo) y si sigue ligada a una factura, nómina o carga de diésel (esas referencias no cambian). Al regresar a un estatus de en proceso, la operación sale de Completados y aparece en Operaciones Activas sin presionar Actualizar. También se puede pasar de Falso a Completado (o al revés) y se queda en Completados. En la bitácora, ese movimiento dice de qué estatus regresó.', detalle: 'Ver CAMBIOS-V00476.md' },
  { fecha: '2026-10-22', version: 'V00475', titulo: 'Reportes de puentes: la ventana muestra el Excel con las referencias de cada unidad y día', resumen: 'Al cargar cualquier Excel de puente (AVI, Puente 3 o Puente Colombia) en Referencias de Puentes se abre la ventana con los renglones del Excel (fecha y hora del cruce, tag, unidad y lo que cobró el puente) y, junto a cada uno, las referencias de esa unidad ese día: la que coincide (con su check para enviarla al Acumulado), otras por asignar, las que ya están en el Acumulado con su referencia (p. ej. PT3-011026-001) y las que aún no se completan. Abre mostrando los renglones con referencias; los chips de arriba cambian a todos los renglones, solo los que coinciden, sin operación por asignar o tag sin unidad. Si las operaciones aún se están cargando, lo dice en lugar de marcar que no coinciden. El Excel que se exporta trae también la columna de referencias.', detalle: 'Ver CAMBIOS-V00475.md' },
  { fecha: '2026-10-22', version: 'V00474', titulo: 'Reglas de Estatus: los movimientos no llevan aduana', resumen: 'En Configuración → Reglas de Estatus, un flujo de Transfer cuyo tráfico es un movimiento (Movimiento LDO, Movimiento NLD…) ya no muestra el selector Aduana, y en la lista dice — en Aduana. Si se cambia el tráfico a un movimiento, la aduana elegida se quita. En el formulario de operación, un movimiento tampoco muestra el campo Aduana.', detalle: 'Ver CAMBIOS-V00474.md' },
  { fecha: '2026-10-22', version: 'V00473', titulo: 'Reglas de Estatus: eliminar flujos y elegir el puente de cada paso', resumen: 'En Configuración → Reglas de Estatus cada flujo de la lista tiene el botón Eliminar: pide confirmación y una nota, y el flujo va a la Papelera de Reciclaje (se puede restaurar). En el paso con Aquí se descuenta el puente, la caseta ya no es fija: se elige el puente de la lista (Automático = el de siempre, según el tráfico) y se puede cambiar su monto; en un flujo de Colombia se eligen la caseta y el puente. Ese puente es el que se pone por defecto en el formulario de operación y el que se cobra al marcar ese estatus (si la tarifa del convenio trae su propia caseta, sigue mandando la de la tarifa).', detalle: 'Ver CAMBIOS-V00473.md' },
  { fecha: '2026-10-21', version: 'V00472', titulo: 'Reglas de Estatus: cambiar la aduana ya no borra los pasos', resumen: 'En Configuración → Reglas de Estatus, al cambiar la aduana (o el tráfico o la carga) de un flujo, los pasos del lienzo se quedan; antes se preguntaba y el lienzo podía quedar en blanco. Si esa combinación aún no tiene flujo guardado, arriba dice que los pasos se guardan ahí al presionar Guardar flujo. Si ya tiene uno, se abre ese. Al guardar se pregunta si se elimina el flujo anterior; si el anterior era el de todas las aduanas, avisa que las operaciones de las demás aduanas se quedarían sin flujo.', detalle: 'Ver CAMBIOS-V00472.md' },
  { fecha: '2026-10-21', version: 'V00471', titulo: 'Puentes: ventana al cruzar, aduana en el formulario y el puente de Reglas de Estatus', resumen: 'Al marcar el Verde (o el estatus que tiene el puente en Reglas de Estatus) sale una ventana: Esta unidad cruzó el puente (nombre), se envió el cobro a Operaciones sin asignar por el monto de (monto); en Colombia dice la caseta y el puente con sus dos montos. En un estatus sin puente (p. ej. Rojo) no sale. En el formulario de operación, en Transfer, la Aduana aparece debajo de Cargada / Vacía. La tarjeta Caseta / Puente dice en qué estatus se cobra según Reglas de Estatus y, si la tarifa del convenio no trae caseta, que el puente viene de Reglas de Estatus; en Colombia muestra también el campo Puente Colombia con su monto.', detalle: 'Ver CAMBIOS-V00471.md' },
  { fecha: '2026-10-21', version: 'V00470', titulo: 'Reglas de Estatus: costo del puente en el paso y aduana solo en Transfer', resumen: 'En Configuración → Reglas de Estatus, al seleccionar el paso donde se descuenta el puente, en Saldo del puente ahora se ve la caseta que se cobra con su costo (solo informativo, del catálogo Tipos de Gastos): Caseta AVI en importación, Caseta Puente III en exportación. Si la aduana del flujo es Colombia aparecen dos campos: la caseta (Caseta Mx Colombia, o Trompo Colombia si es trompo) y el puente (Puente Mx Colombia). Si la tarifa del convenio trae su propia caseta, se cobra la de la tarifa. El selector Aduana solo aparece en los flujos de Transfer.', detalle: 'Ver CAMBIOS-V00470.md' },
  { fecha: '2026-10-21', version: 'V00469', titulo: 'Reglas de Estatus por aduana y revisión del cobro de puentes', resumen: 'En Configuración → Reglas de Estatus hay un selector nuevo, Aduana, al lado de Carga: un flujo puede ser solo de una aduana (p. ej. 800 Colombia) y las operaciones de esa aduana lo usan; las demás siguen con el general (Todas). La lista de flujos muestra la columna Aduana. Puentes: si un clic pasa por Verde y sigue solo a otro estatus, el puente ya se cobra en el Verde (antes esperaba a Completado); una operación que quedó con el puente en $0 ya se puede cobrar; el formulario ya no regresa un puente viejo al guardar (p. ej. el que se cambió en Referencias de Puentes mientras estaba abierto) y cobra con la misma regla que Operaciones Activas y el servidor (con aduana Colombia, solo casetas de Colombia; la fecha de hoy en hora local). En Enviar al Acumulado cada operación va a la referencia de su puente (antes las de otro puente se perdían sin aviso) y ya no se crean referencias vacías. Las tarjetas de casetas cuentan cualquier otro puente en Puente III, igual que Referencias de Puentes.', detalle: 'Ver CAMBIOS-V00469.md' },
  { fecha: '2026-10-21', version: 'V00468', titulo: 'Estadísticas por Aduana: solo cruces de importación y exportación', resumen: 'En Estadísticas → Desglose → Aduana ya no se cuentan los movimientos: solo los cruces de importación y exportación de Transfer y Logística (los fletes y lo sin clasificar tampoco). Arriba de la tabla se explica en amarillo. Si la Aduana se usa como sub-nivel de otro desglose, lo que no es cruce sale como No cruza.', detalle: 'DesgloseJerarquico.soloPara (filtro de la raíz) + esCruceOp en EstadisticasDashboard; norm/textoDeOp/movimientoDeOp fuera del componente.' },
  { fecha: '2026-10-21', version: 'V00467', titulo: 'Estadísticas por Aduana y reportes de Puente 3 y Puente Colombia', resumen: 'Estadísticas: el Desglose tiene una dimensión nueva, Aduana (por qué aduana cruzó la unidad), como botón y en Desglosar en. Referencias de Puentes: el botón ahora es Cargar reporte de puente y reconoce solo el reporte del AVI, el de Puente 3 (estado de cuenta de Comercio Mundial, con sus dos hojas) y el de Puente Colombia. Cada cruce se busca con el TAG de ese puente en Unidades Propias (TAG Puente 3, TAG Puente Colombia); en Colombia, si la unidad no tiene su TAG, se toma por el # económico. En Colombia los dos cobros de cada cruce (el puente $90 y la caseta $129.60) se juntan en uno y se comparan con la caseta más el puente de la operación. Las operaciones de ese mismo puente se buscan primero.', detalle: 'reporteAvi.ts: leerReportePuente + unirCruces (formatos AVI/PT3/PTC, hojas sin repetir, cobros de Colombia), tag por puente, # económico, penalización a otro puente; PanelReporteAvi por puente; Estadísticas: dimensión aduana.' },
  { fecha: '2026-10-20', version: 'V00466', titulo: 'Reporte AVI: busca solo en Operaciones sin asignar y abre una ventana con las que coinciden', resumen: 'Al cargar el reporte del AVI en Referencias de Puentes se abre una ventana con las operaciones de Operaciones sin asignar que coinciden con un cruce (las del Acumulado y las que aún no se completan ya no se toman). Cada una trae su check, la hora del cruce y del Verde, lo que cobró el AVI y lo que hay que revisar; si la unidad tiene otra operación ese día en el Acumulado, lo avisa. Desde ahí se envían al Acumulado o solo se marcan en la tabla. Los cruces que no coinciden quedan plegados abajo. Ya no se muestra el lugar (todo el reporte es del AVI). Al cerrar la ventana, el botón Coincidencias AVI la vuelve a abrir.', detalle: 'reporteAvi.ts sin estados enAcumulado/noCompletada/otroTrafico ni lugar; otrasDelDia para avisos; PanelReporteAvi pasa a modal (pra-).' },
  { fecha: '2026-10-20', version: 'V00465', titulo: 'Puentes: el puente del convenio al poner la unidad, el TAG de cada puente y checks alineados', resumen: 'En el formulario de operación, la tarjeta Caseta / Puente aparece en cuanto se pone la unidad y ya trae el puente que corresponde por el convenio y su tarifa (la caseta de los gastos incluidos, con su monto; si la tarifa no trae, Colombia o el tráfico), con el mismo criterio con el que se cobra al marcar Verde. Si se cambia a mano, ya no se toca. En la ficha de la operación (Unidad y Operador) y en esa tarjeta sale el TAG de la unidad para ese puente: TAG AVI, TAG Puente 3 o TAG Puente Colombia (o "sin registrar" si la unidad no lo tiene). En Referencias de Puentes → Acumulado, los checks de cada referencia quedan alineados con el de Seleccionar todas. Además, el cobro del puente ya encuentra la tarifa del convenio aunque el detalle la guarde como Tipo de convenio.', detalle: 'casetaPrevista + tarifaDeDetalleConvenio (shared/dominio/cobroPuente, también en el servidor: desplegar functions:operacionEscrita); TagPuenteUnidad + tagPuente.ts; FormularioOperacion: puenteVisible con unidad y asignación por convenio; Acumulado sin td flex.' },
  { fecha: '2026-10-20', version: 'V00464', titulo: 'Referencias de Puentes: cargar el reporte del AVI y encontrar las operaciones de cada cruce', resumen: 'En Operaciones sin asignar hay un botón Cargar reporte AVI: se sube el Excel de cruces que se descarga del portal del puente (fecha y hora del cruce, TAG #, lugar y monto). Cada tag se une con su unidad por el TAG AVI de Unidades Propias y con la operación de esa unidad ese día; si la unidad cruzó varias veces, cada cruce va con la operación cuyo Verde quedó más cerca de la hora del cruce. Se ve cada cruce con su resultado (coincide, ya está en el Acumulado, aún sin completar, sin operación o tag sin unidad) y avisos de monto o puente distintos. El botón Seleccionar las que coinciden las deja marcadas en la tabla para Enviar al Acumulado, y el resultado se puede exportar a Excel.', detalle: 'Ver CAMBIOS-V00464.md' },
  { fecha: '2026-10-19', version: 'V00463', titulo: 'Operaciones: ya no aparece el aviso "internal" al guardar una operación nueva', resumen: 'El aviso "internal" salía cuando el navegador no recibía respuesta del servidor al guardar una operación nueva (se cortaba la conexión o el servidor no contestaba a tiempo) y obligaba a volver a guardar. Ahora la app lo reintenta sola hasta 3 veces sin duplicar la operación. Si aun así no se puede, explica en español qué pasó, los datos se quedan en el formulario y el siguiente Guardar tampoco duplica: si algún intento sí llegó, usa esa misma operación con los datos actuales. Cada reintento y cada falla quedan en el Historial de actividad (Operaciones · Reintento / Error) para saber cuándo y a quién le pasa.', detalle: 'Ver CAMBIOS-V00463.md' },
  { fecha: '2026-10-17', version: 'V00462', titulo: 'Operaciones: al abrir una operación su tipo de cambio pasa solo al de su fecha de servicio', resumen: 'Si una operación se guardó con el tipo de cambio de otro día, al abrirla ya toma sola el oficial de su fecha de servicio y lo dice en azul ("antes tenía…"); queda corregida al presionar Guardar. Al cambiar la fecha toma el de la nueva fecha, y al regresar a la fecha original vuelve al oficial de esa fecha (antes regresaba el que traía). Las operaciones ya facturadas no se cambian solas (cambiaría una factura emitida): se marcan en amarillo.', detalle: 'Ver CAMBIOS-V00462.md' },
  { fecha: '2026-10-16', version: 'V00461', titulo: 'Operaciones: el tipo de cambio es siempre el de la fecha de servicio', resumen: 'Al abrir una operación de días anteriores, el formulario le ponía el tipo de cambio de HOY y se guardaba así; también se quedaba el de la fecha anterior al cambiarla a un día sin registro, y un tipo de cambio capturado en la noche se tomaba como el del día siguiente. Ahora la operación usa el tipo de cambio de su fecha de servicio (sábado y domingo sin registro: el del viernes). Debajo de la fecha y del campo Tipo de Cambio se ve el oficial de esa fecha; si la operación trae otro, aparece en amarillo con el botón Usar el oficial (se guarda al Guardar). La tarjeta Tipo de cambio ya no dice "DOF de hoy" con el de ayer.', detalle: 'Ver CAMBIOS-V00461.md' },
  { fecha: '2026-10-16', version: 'V00460', titulo: 'Últimas capturas de diesel: descuento y costo real', resumen: 'Al presionar la tarjeta Diesel de Operaciones Activas, la lista de las últimas capturas trae dos columnas nuevas: Descuento (Murphy descuenta $0.20 por galón; los demás proveedores no tienen) y Costo real (por galón menos el descuento). La etiqueta "más bajo" ahora marca el costo real más bajo de cada día.', detalle: 'Ver CAMBIOS-V00460.md' },
  { fecha: '2026-10-16', version: 'V00459', titulo: 'Diesel: confirmar el cobro real (descuento de Murphy) y el saldo con lo cobrado', resumen: 'En Referencias del Diesel → Historial de Referencias cada carga tiene el botón Confirmar cobro ($): ahí se corrigen los galones que realmente se cargaron y se capturan el Descuento y el Monto cobrado tal como vienen en el reporte de Murphy (Discount y Net of Discount). Mientras no se capturan, en las cargas de Murphy desde el 17 de octubre se estima un descuento de $0.20 por galón; las cargas anteriores siguen igual. La tabla, el resumen, la ficha y el Excel muestran galones autorizados y su total, galones cargados, sin descuento, descuento, cobrado, diferencia de galones y diferencia de monto, y cuántas cargas faltan por confirmar. El Saldo Diesel (pestaña Saldos, tarjeta de Operaciones Activas y su historial) ahora descuenta lo cobrado.', detalle: 'Ver CAMBIOS-V00459.md' },
  { fecha: '2026-10-16', version: 'V00458', titulo: 'Otros Cruces: el puente viene en Caseta AVI y se puede cambiar', resumen: 'En Referencias de Puentes → Otros Cruces → + Agregar cruce, el puente viene elegido en Caseta AVI, pero ahora se puede escoger cualquier otro puente de la lista. Al cambiarlo se pone el monto de ese puente y la lista de referencias muestra las de ese puente (o crear una nueva con su consecutivo).', detalle: 'Ver CAMBIOS-V00458.md' },
  { fecha: '2026-10-16', version: 'V00457', titulo: 'TAG de puentes en Unidades Propias, Acumulado en Referencias de Puentes y Saldo Diesel con Actualizar saldo e historial', resumen: 'Unidades Propias tiene tres campos nuevos: TAG AVI, TAG PUENTE 3 y TAG PUENTE COLOMBIA (también se pueden mostrar como columnas de la tabla y salen en el Excel); TAG AVC se queda. En Referencias de Puentes, Historial de referencias ahora se llama Acumulado, se quitó la pestaña Historial manual (anterior) y el botón Eliminar todas, en Operaciones sin asignar solo aparecen las operaciones completadas y en Otros Cruces el puente es siempre la Caseta AVI. La tarjeta Saldo Diesel de Operaciones Activas tiene el botón Actualizar saldo, que abre el mismo formulario Agregar saldo de diesel de Referencias del Diesel y lo guarda en sus Saldos, y al presionar la tarjeta se ve el historial del saldo con rango de fechas: los saldos agregados, lo cargado cada día y el saldo que queda; al abrir un día se ven sus cargas.', detalle: 'Ver CAMBIOS-V00457.md' },
  { fecha: '2026-10-16', version: 'V00456', titulo: 'Operaciones Activas: tarjetas más bajas, pestaña Completadas hoy, historial de TC y diesel y tabla rediseñada', resumen: 'Las tarjetas del resumen del día son más bajas. Al presionar Completadas hoy en la tarjeta Operaciones del día se abre la pestaña Completadas hoy, al lado de Rentas, con los servicios completados del día (se cierra con la ✕). Al presionar la tarjeta Tipo de cambio o Diesel se ven los últimos registros capturados: el tipo de cambio con su variación y el diesel con su proveedor, precio por galón y por litro, marcando el más bajo de cada día. La tabla de Operaciones Activas tiene un diseño nuevo: botón Nueva operación arriba, una sola barra de búsqueda y acciones, pestañas con el color de cada tipo, filas con una franja del color del tipo, status y tráfico como etiquetas y paginación más clara.' },
  { fecha: '2026-10-16', version: 'V00455', titulo: 'Tarjetas de Operaciones Activas: completadas en Operaciones del día, TC y Diesel separados y saldos de puente', resumen: 'La tarjeta Completadas hoy pasa dentro de Operaciones del día, con su avance y el desglose por tipo. Tipo de cambio y Diesel tienen cada uno su tarjeta. En las tarjetas de puente, Actualizar saldo abre el mismo formulario Agregar saldo de Referencias de Puentes, con la caseta de esa tarjeta ya elegida (Caseta AVI, Caseta Puente III o Caseta Mx Colombia), y se guarda en sus Saldos. Al presionar una tarjeta de puente se ven los movimientos de su saldo, como el Historial de referencias, con rango de fechas: las referencias que lo descuentan y los saldos agregados.' },
  { fecha: '2026-10-15', version: 'V00454', titulo: 'Referencias de Puentes: cambiar el puente sin avisos y la operación va a ese puente', resumen: 'En Operaciones sin asignar, al elegir otro puente en la lista se cambia de inmediato, sin preguntar, con el monto y la moneda de ese puente (Colombia agrega el Puente Mx Colombia). Ya no aparece Debe ser Colombia y Asignar monto del puente ya no regresa a Colombia lo que elegiste. Al enviarla al Historial, la operación va a la referencia del puente que elegiste: AVI, Puente III o Colombia, aunque su convenio sea de Colombia. Las referencias ya no marcan Otro puente por el convenio.' },
  { fecha: '2026-10-15', version: 'V00453', titulo: 'App móvil: historial y pagos del operador, historial completo del cliente', resumen: 'En la app móvil el operador tiene dos pestañas nuevas: Historial, con todas sus operaciones mes por mes y lo que le pagó cada una, y Mis pagos, donde ve cuánto lleva ganado en la semana (lo pagado, lo que está por cobrar y lo que sigue en curso) y todas sus nóminas con su recibo. El cliente ahora puede ver en la app TODAS las operaciones que se han hecho, mes por mes, no solo las de los últimos 60 días. En Usuarios hay un botón "📱 Nuevo acceso de cliente" para darle a una empresa acceso a la app, un filtro para ver solo a los clientes y, en la lista, a qué empresas da acceso cada uno.', detalle: 'portalCliente portal-v2: accion historial {desde, hasta} (máx. 93 días, índice existente empresasIds+fechaServicioISO, respaldo clientePaga/clienteMercancia+fechaServicio); papel y propiedad también por clientePagaId/clienteMercanciaId. Índice nuevo operaciones(operador, fechaServicioISO desc) para el historial y la semana del operador (la app funciona sin él, leyendo más). UsuariosDashboard: abrirNuevoCliente, filtro por tipo de acceso, empresas del cliente en la fila.' },
  { fecha: '2026-10-14', version: 'V00452', titulo: 'Pagos más rápido: "Registrar Pago" abre al instante', resumen: 'Al presionar "Registrar Pago" ya no se espera de 8 a 10 segundos: la lista de facturas se va cargando en segundo plano mientras ves los pagos y al abrir la ventana ya está. Volver a abrirla es inmediato. Los saldos se actualizan solos cuando se registra, edita o elimina un pago (también si lo hace otra persona), por eso ya no están los botones "Recargar". Mientras llegan los saldos del servidor se ve "Actualizando saldos…" y el botón Guardar espera; si una factura elegida se pagó mientras capturabas, se avisa y se corrige antes de guardar. La pantalla de Pagos carga menos cosas al entrar (Excel, PDF y el formulario de operaciones se cargan solo cuando se usan) y la app arranca más ligera.', detalle: 'Ver CAMBIOS-V00452.md' },
  { fecha: '2026-10-14', version: 'V00451', titulo: 'Facturas que se quedaban "pendientes" y carga de varios archivos en toda la app', resumen: 'Facturas de Clientes y Proveedores: se corrigió lo que hacía que una operación ya facturada siguiera apareciendo pendiente o que el documento subido no se viera. Antes de facturar se revisa en el servidor si la operación ya está en otra factura y si ese número de factura ya existe (antes se creaba una segunda factura con el mismo número y el documento quedaba escondido en ella). Abrir "Editar factura" solo para subir el documento ya no cambia el total (en facturas en dólares lo cambiaba a pesos y en Pagos quedaba saldo). Las operaciones importadas con un identificador interno distinto ya se pueden facturar. La ficha de Servicios Completados muestra la factura al día. Archivos: en todos los lugares donde se suben archivos (pagos, documentos de factura, tarifario firmado, mantenimiento, herramientas, fotos de diésel, documentos de la operación y expedientes) se pueden subir varios a la vez, verlos en el mismo formulario antes de guardar, reemplazarlos o quitarlos. Hasta 10 por registro; en los expedientes (colaboradores, empresas, unidades, operaciones) sin límite. Las fotos y el logo siguen siendo uno solo. En Mantenimiento el archivo ya se guarda (antes se perdía).', detalle: 'Ver CAMBIOS-V00451.md' },
  { fecha: '2026-10-13', version: 'V00450', titulo: 'REF Cliente duplicada en Revisión y comprobante de pago con vista previa', resumen: 'Si una operación tiene la misma Ref Cliente que otra (de cualquier cliente; no cuentan mayúsculas, espacios, "N/A", canceladas ni de prueba), sale una notificación y pasa a la nueva pestaña Revisión: en Operaciones Activas y, si está pendiente de facturar, en Facturación de Clientes (ahí sale de "Asignar Operaciones" y no se puede facturar hasta revisarla). En Revisión se ve con qué operación choca; se corrige la Ref o se marca "No es duplicado" y regresa a su lista (si después cambia la Ref, se vuelve a revisar). La campana muestra cuántas hay en Revisión, y el formulario avisa al capturar una Ref Cliente que ya existe. En Pagos, el comprobante se agrega arrastrándolo o con clic, se ve en el mismo formulario (PDF o imagen) y se puede reemplazar antes de guardar, también al editar un pago.', detalle: 'refClienteDuplicado.ts (clave sin espacios/mayúsculas, variantes para where in), refClienteDuplicadoServidor.ts (consulta por lotes de 30 con cola de 4, 5 min por Ref, tope de 400 Ref por pantalla, se corrige con operacionesBus al guardar/cancelar/eliminar, marcarNoDuplicado → refClienteRevisado/Por/En), facturar se niega con Ref en Revisión o en verificación, useRefClienteDuplicados, RevisionRefCliente, avisos.ts + AvisosFlotantes (notificaciones y campana). Pagos: AdjuntoComprobante (zona de arrastre, máx. 20 MB, vista previa, reemplazar). Sin reglas, índices ni funciones nuevas.' },
  { fecha: '2026-10-12', version: 'V00449', titulo: 'Animación de espera al filtrar y "Varios" en MTTO', resumen: 'Al buscar o filtrar, mientras llega la información se ve una animación de espera en lugar de la pantalla en blanco, de "No hay registros" o de números en cero: en Servicios Completados y Cancelados, Operaciones, Facturación, Pagos, Estadísticas, Reportes, Resumen del día, Empresas, Convenios, Tarifarios, Nómina, Diésel, Puentes, Catálogos, Usuarios, Autorizaciones y demás listas. En un gasto de MTTO, los campos Unidad y Operador tienen la opción "Varios" para insumos que se usan en varias unidades (aceite, anticongelante, desengrasante).', detalle: 'Componente compartido CargandoDatos (src/shared/components). Banderas de "primera respuesta recibida" en listeners que no la tenían y banderas de carga encendidas en el mismo clic del filtro (antes un pintado o un await obtenerFlags() después). MTTO: MTTO_VARIOS se guarda como valor fijo (como Oficina); las listas de Unidad y Operador se abren al enfocar y se cierran al salir del campo.' },
  { fecha: '2026-10-12', version: 'V00448', titulo: 'Revisión completa: facturas, permisos y documentos más seguros', resumen: 'Se revisó todo lo que cambió desde la V00434 y se corrigió lo que podía dejar datos mal. Cambiar el número de factura de una operación sin cambiarlo de verdad (o dar Guardar dos veces) ya no crea una factura repetida. Quitar o mover una operación de una factura que comparte folio ya no le deja saldo. Si un catálogo no llega del servidor (sin internet), lo que guarda avisa en lugar de seguir como si estuviera vacío, y los PDF avisan en vez de salir con N/A. Los totales de Facturación se muestran con la misma regla que Pagos. Un texto raro capturado en una descripción ya no puede ejecutarse al generar un PDF, la Relación de Compras o un reporte. Eliminar con papelera ya no borra facturas ni saldos (las facturas se borran desde Facturación). Se dejaron listas, sin publicar, reglas de seguridad más estrictas: un usuario dado de baja o desactivado deja de guardar y de subir archivos al momento.', detalle: 'Code Review V00447. Dinero: moverOperacionFactura idempotente (servidor y web), totalesTrasCambioDeOps parte del total guardado aunque sea 0, cascada de montos no pone en 0 un renglón con monto y usa la regla única con dineroPorServidor, reconciliar marca totales manuales solo con --manuales. Datos: obtenerVivo/obtenerCatalogo rechazan si no llegó nada (antes []), primer snapshot de un listener reabierto se publica siempre, integridad de convenios se niega con tarifarios/maestros vacíos, banderas se vuelven a esperar tras cerrar sesión, catálogos de peaje frescos, fechaServicioISO null explícito (orderBy). Seguridad: gestionarUsuario detrás de usuariosPorServidor, papelera sin facturas/saldos/usos/eventos, escapes HTML en PDF/impresión, reglas (sin publicar): escritor exige perfil vigente, catalogo_roles solo admin, Storage exige perfil para subir. Functions en Node 22.' },
  { fecha: '2026-10-11', version: 'V00447', titulo: 'Pantallas en orden y arranque más rápido', resumen: 'Se corrigió que algunas pantallas se vieran desacomodadas después de abrir otra: por ejemplo, el panel de Filtros de Servicios Completados después de entrar a Cancelados (también Empresas/Empleados, Catálogos/Contactos/Combustible, Reportes/Remolques/Roles, Direcciones/Deducciones y Unidades/Usuarios). La app abre más rápido: ya no espera varias revisiones con el servidor antes de mostrar el menú y las operaciones. El formulario de Nueva operación abre al instante, y abrir una operación desde Facturación o Pagos ya no descarga todos los catálogos. Abrir la app en una segunda pestaña ya aprovecha lo guardado en el navegador.', detalle: 'Prefijos de CSS propios por archivo + scripts/verificar-css.mjs; arranque con perfil y roles desde la caché local, banderas al iniciar sesión, revisión de red en segundo plano si ningún rol la exige; persistentMultipleTabManager con tope en almacenSesion; sin índices automáticos de la caché local; gracia de escucha 30 min y Operaciones siempre escuchando; catálogos del formulario precalentados; EditorOperacionEmbebido sin getDocs de 17 catálogos; candados contra descargas dobles en Facturación y Operaciones; useMapaEstable en Facturación.' },
  { fecha: '2026-10-11', version: 'V00446', titulo: 'La app vuelve a ser rápida', resumen: 'Después de los últimos ajustes los módulos tardaban más en abrir y en cambiar de uno a otro. Se corrigió: las pantallas ya no se vuelven a dibujar una vez por cada lista que llega (empresas, monedas, convenios…), las que están ocultas no trabajan en segundo plano, regresar a un módulo ya no lo vuelve a cargar, y abrir una operación o un reporte ya no espera al servidor. En pruebas, abrir Facturación pasó de 16 repintados a 4.', detalle: 'Avisos agrupados en coleccionesVivas, sin repintado por confirmación del servidor ni en módulos ocultos, catálogos abiertos toda la sesión, obtenerCatalogo rápido (fresco solo donde se escribe), gracia de 10 min en listeners de módulos ocultos, índices de la caché local de Firestore, npm run medir:render.' },
  { fecha: '2026-10-10', version: 'V00445', titulo: 'Operaciones Activas vuelve a abrir en desarrollo', resumen: 'Se corrigió un error que tiraba la pantalla de Operaciones Activas al abrirla en el ambiente de desarrollo (en producción no se notaba). Además se quitó una clave de Banxico que ya no se usaba y se agregó una revisión automática que abre cada módulo de la app para avisar si alguno se rompe al entrar.', detalle: 'statusServicioOrdenado (sin uso desde V00378) se leía dentro de su propio useMemo → ReferenceError en dev. VITE_BANXICO_TOKEN fuera de .env/.env.example. Prueba de humo de 31 módulos con banderas apagadas y encendidas.' },
  { fecha: '2026-10-10', version: 'V00444', titulo: 'Orden interno del código (sin cambios en pantalla)', resumen: 'Se ordenó por dentro el código de Operaciones, Facturación, Servicios Completados y el formulario de operación: las partes que estaban copiadas en dos o tres pantallas ahora existen una sola vez y los archivos más grandes se partieron en piezas. Nada cambia en lo que ves; hace más fácil y seguro corregir y mejorar estas pantallas.', detalle: 'Fase 8: useOperacionesActivas, useOperacionesFacturables, selectores de Facturación y formatos de operaciones (antes copiados), piezas del formulario y de Completados en archivos propios, 25 efectos con useEffectEvent en lugar de eslint-disable, trinquete de exhaustive-deps. 8.2 (unir Facturación) pendiente de decisión; 8.4 (costos aparte) diseñado.' },
  { fecha: '2026-10-10', version: 'V00443', titulo: 'Cada pantalla pide solo lo que muestra (listo para encender)', resumen: 'Se preparó que Operaciones, Servicios Completados y Cancelados, Facturación, Pagos, Empresas, Convenios, Reportes y el Resumen del día dejen de descargar todas las operaciones de la historia: pedirán solo el rango de fechas, la empresa o las pendientes que se están viendo, de 50 en 50 cuando aplica. Eso hace las pantallas más rápidas y gasta muchas menos lecturas. Hoy no cambia nada en pantalla: se enciende después de poner al día los datos. Ya funcionan desde ahora: la remisión y el rate de una factura con más de 60 operaciones salen completos, y Servicios Completados vuelve a buscar cuando cambias el rango de fechas.', detalle: 'Fase 7: src/shared/data/consultas.ts (páginas con cursor, topes con aviso, lotes por ID de 30 en paralelo, contadores usos/), bandera consultasCanonicas, 9 índices compuestos, sin cortes silenciosos (60/150/10), escrituras en lote en Detalles de Convenio, useFlagsCargadas.' },
  { fecha: '2026-10-10', version: 'V00442', titulo: 'El servidor mantiene los nombres y cuenta los usos (listo para encender)', resumen: 'El servidor hace menos trabajo repetido cada vez que se guarda una operación o una factura, y si algo falla por un momento lo vuelve a intentar solo en lugar de perder el cambio. Se preparó que, al renombrar una empresa, un status, un tipo de operación, una unidad o un empleado, el nombre nuevo se copie solo a todas las operaciones, facturas y pagos (sin botones de "Sincronizar"), y que cada empresa y convenio lleve la cuenta de cuántas operaciones lo usan. Hoy no cambia nada en pantalla: se enciende después de correr la puesta al día de nombres y el recuento.', detalle: 'Fase 6: operacionMontoCambiado unido a operacionEscrita, listas blancas en los triggers, callables que escriben agregados y canónicos de una vez, retry con descarte a las 24 h y eventos_procesados con TTL, propagación de nombres con un solo mapa (bandera propagacionEnServidor), contadores usos/{tipo}_{id}, fieldOverrides en índices.' },
  { fecha: '2026-10-10', version: 'V00441', titulo: 'Facturas, pagos y peaje calculados en el servidor (listo para encender)', resumen: 'Se preparó todo para que facturar, editar facturas y aplicar o eliminar pagos los haga el servidor de un solo golpe: si dos personas trabajan la misma factura, o se corta el internet a la mitad, ya no quedan saldos mal ni facturas duplicadas, y lo que se pague de más queda como saldo a favor. El peaje del puente también lo podrá cobrar el servidor, incluido lo que marquen los operadores desde la app móvil, y la tarjeta de Saldo Diesel cargará mucho más rápido. Hoy no cambia nada en pantalla: cada parte se enciende por separado después de revisar con el negocio el reporte de diferencias de las facturas.', detalle: 'Fase 5: regla única de dinero (src/shared/dominio/dinero.ts), planes de facturación/pagos, 10 callables con transacción (bandera dineroPorServidor), renglones/aplicaciones como tablas hijas, reglas de seguridad para campos de dinero (P1), reconciliación de facturas (P3), cobro de puente en operacionEscrita (cobroPuenteEnServidor) y saldo corriente de diésel (saldosCorrientes, P2).' },
  { fecha: '2026-10-10', version: 'V00440', titulo: 'Base de datos preparada para búsquedas rápidas', resumen: 'Cada operación guarda ahora, junto a sus datos de siempre, una versión ordenada de la fecha, las empresas que participan, su estado (activa, completada, falso o cancelada) y si está pendiente de facturar. Todavía no cambia ninguna pantalla: es la base para que, más adelante, Operaciones, Completados, Facturación y Reportes consulten solo lo necesario en lugar de descargar miles de registros. El formulario de operación guarda los montos como número.', detalle: 'Fase 4: operacionCanonica.ts (compartido con el servidor), trigger operacionEscrita y crearOperacion con campos canónicos (bandera canonicosEnServidor), migración functions/scripts/migrarEsquemaV2.ts con simulación y reportes (sin correr: punto de parada P2).' },
  { fecha: '2026-10-10', version: 'V00439', titulo: 'Catálogos al día en toda la app', resumen: 'Empresas, unidades, remolques, convenios, monedas, status y demás catálogos se leen una sola vez para toda la app y se actualizan solos: si alguien edita una empresa o un convenio, el cambio se ve al momento en Operaciones, Facturación y Estadísticas sin limpiar caché. Los documentos PDF y la Confirmación de Tarifa ya no salen con datos vacíos si se descargan apenas se abre la ficha. Cambio a revisar: el permiso para editar la referencia ya no se da a los roles cuyo nombre solo contiene "ADMIN" (como ADMINISTRATIVO); si lo necesitan, se agrega el permiso EDITAR REF a ese rol en Roles.', detalle: 'Fase 3: src/types/firestore.ts, convertidores, useCatalogo/obtenerCatalogo (un listener compartido por colección), useColeccionViva, permisos desde la sesión, constantes y moneda compartidas, limpieza de cachés legadas en localStorage.' },
  { fecha: '2026-10-10', version: 'V00438', titulo: 'Pantallas más ágiles', resumen: 'Escribir en el buscador de arriba ya no congela la pantalla. Los módulos que no estás viendo dejan de consultar la base de datos mientras están ocultos y se ponen al día al volver, sin perder filtros ni página. Pasar el mouse por las tablas, ordenar y buscar en Facturación y Estadísticas es más rápido. Si se publica una versión nueva mientras tienes un formulario abierto, la app espera a que lo guardes y cierres para actualizarse.', detalle: 'Fase 2: BuscadorTopbar, memo de módulos, listeners solo visibles, hover en CSS, llaves de orden precalculadas, Suspense por módulo, recarga protegida por formularios abiertos.' },
  { fecha: '2026-10-10', version: 'V00437', titulo: 'Seguridad de acceso y pagos sin choques', resumen: 'Una cuenta sin perfil en Usuarios, desactivada o de cliente ya no puede entrar y el inicio de sesión explica el motivo. Si un administrador cambia los roles de alguien se aplican al momento, y si lo da de baja su sesión se cierra. En Roles hay una casilla para exigir la red de la oficina. Aplicar, editar o borrar un pago revisa la factura en ese momento: si otra persona ya le aplicó un pago, avisa y no guarda nada. La nómina revisa que ninguna operación esté ya pagada en otra nómina y su folio ya no se repite. No se puede eliminar una factura con pagos y su total se recalcula al agregar o quitar operaciones.', detalle: 'Fase 1: claims de acceso (usuarioEscrito, sincronizarClaims, gestionarUsuario), firestore.rules nuevas (sin publicar), zod en crearOperacion, verificarIntegridad solo admin, eliminarConPapelera, transacciones en Pagos y Nómina.' },
  { fecha: '2026-10-10', version: 'V00436', titulo: 'Preparación para acelerar el sistema (sin cambios visibles)', resumen: 'Se agregaron herramientas internas para medir cuántas lecturas hace cada pantalla, pruebas automáticas y las reglas de seguridad guardadas junto con el código. No cambia nada de lo que se ve; es la base para las siguientes mejoras de velocidad.', detalle: 'Fase 0 del plan: medidor de lecturas (npm run dev:medir), vitest, trinquete de ESLint, firestore.rules/indexes en el repo, lógica pura compartida en src/shared/dominio.' },
  { fecha: '2026-10-10', version: 'V00435', titulo: 'Acceso de clientes para la app móvil', resumen: 'En Usuarios hay una nueva casilla "Acceso de CLIENTE (solo app móvil)": al marcarla se eligen una o varias empresas y ese usuario podrá entrar a la app móvil de Roelca para ver sus servicios en proceso, el trayecto de su mercancía en el mapa y su estado de cuenta (lo que debe y lo que ha pagado). Un usuario de cliente no puede entrar a este sistema web. Los operadores usan la misma app móvil con su usuario de siempre para marcar sus horarios y registrar su trayecto.', detalle: 'Cloud Function nueva portalCliente (functions/src/portalClientes.ts) como única puerta de datos del cliente; crearOperacion, renumerarOperacion y verificarIntegridad ahora exigen usuario de personal (functions/src/acceso.ts); campos tipoUsuario / empresasClienteIds / empresasClienteNombres en usuarios; Login bloquea a los clientes; colección nueva rastreo_operaciones (GPS por operación).' },
  { fecha: '2026-10-09', hora: '17:15', version: 'V00434', titulo: 'Trompos de Roelca no cobrables', resumen: 'Los trompos cuyo Cliente (Paga) es Roelca son no cobrables: en el formulario el monto de cobro queda en $0 (con un aviso) y se guarda así. En el Resumen Diario de Operaciones esos trompos ya no se cuentan en TROMPO sino en OTROS NO COBRABLES, y se restan de las Referencias Cobrables.' },
  { fecha: '2026-10-08', hora: '20:30', version: 'V00433', titulo: 'Cambiar el sueldo del operador con motivo', resumen: 'En el detalle de Operaciones Activas, en el de Servicios Completados y en el formulario de la operación hay un botón Cambiar sueldo junto al Sueldo del Operador. Pide el nuevo monto y el motivo (obligatorio); el Sueldo Total se recalcula y el motivo queda como nota en el detalle de la operación con quién lo cambió, cuándo y de cuánto a cuánto. En el formulario el sueldo ya solo se cambia con este botón. Si la nómina ya se pagó, avisa antes de cambiarlo.' },
  { fecha: '2026-10-08', hora: '17:10', version: 'V00432', titulo: 'Operaciones Activas sin canceladas, falsos ni completadas', resumen: 'Operaciones Activas ya no muestra operaciones Canceladas, Falsas ni Servicios Completados: se excluyen por su status y también por el nombre del status. Si una operación se cancela, se marca como falso o se completa mientras la lista está abierta, desaparece de la lista al instante (antes se quedaba hasta recargar).' },
  { fecha: '2026-10-08', hora: '17:00', version: 'V00431', titulo: 'Botón Cancelar referencia visible sin reglas de estatus', resumen: 'Corrección: el botón Cancelar referencia no aparecía en las operaciones sin reglas de estatus (por ejemplo, Logística Fletes de Importación con carga Rabón Hazmat). Ahora aparece junto a Registrar Status y dentro de Registrar Movimiento en cuanto se confirma que la operación no tiene flujo configurado.' },
  { fecha: '2026-10-08', hora: '16:45', version: 'V00430', titulo: 'Grupos de convenios más claros y cancelar referencias sin reglas de estatus', resumen: 'En Convenio de Clientes y de Proveedores, al desplegar un grupo de convenios con varios costos, sus convenios se ven distintos al resto: fondo azul, barra azul a la izquierda, sangría con conector y una línea que cierra el grupo. En el detalle de la operación, si su Servicio + Tráfico + Carga no tiene reglas de estatus, aparece el botón Cancelar referencia (también dentro de Registrar Movimiento); pide el motivo y registra quién y cuándo la canceló, igual que el formulario.' },
  { fecha: '2026-10-07', hora: '22:00', version: 'V00429', titulo: 'Convenios agrupados, conteo, status de las operaciones y convenios siempre completos', resumen: 'En Convenio de Clientes y de Proveedores, los convenios con el mismo nombre y varios costos se agrupan en una fila con un ícono que despliega cada convenio por separado, con sus operaciones, su status y su costo. El detalle del tarifario y el modal de convenios de la operación tienen una columna # de conteo. El número de operaciones muestra en qué status está cada una (Servicio Completado, Cancelado, Salida del Patio, etc.); en el tarifario, al hacer clic en el número se ve la lista de operaciones con su status. Ningún convenio puede quedar sin cliente o proveedor, sin tarifa o sin su llave al tarifario: se reparan solos al abrir Convenios, al agregarlos, al editarlos, al aprobar o sincronizar un tarifario, y también desde el servidor; los que no se puedan resolver se marcan con un aviso rojo.' },
  { fecha: '2026-10-07', hora: '04:30', version: 'V00428', titulo: 'Tarifario, Convenios y Operaciones dicen lo mismo', resumen: 'El modal de convenios de la operación ahora muestra todas las tarifas del tarifario del cliente, aunque su convenio haya quedado ligado a un convenio maestro borrado o unido (como los Trompo). Sincronizar convenios ya no borra convenios por error cuando dos tarifas tienen el mismo nombre y distinto monto ni borra convenios con operaciones; además reapunta los convenios desligados al convenio del cliente, alinea su status con el del tarifario, vuelve a crear los que dicen Sin convenio con su mismo número y agrega al tarifario los convenios del cliente que no estaban en él. El detalle del tarifario marca con Desligado las líneas que no salían en Operaciones y avisa cuántos convenios del cliente están fuera del tarifario.' },
  { fecha: '2026-10-06', hora: '16:00', version: 'V00427', titulo: 'Carta de Instrucciones según el tipo de operación', resumen: 'En la Carta de Instrucciones, el bloque Facturar a, la Fecha y Hora de Cita y el bloque de Instrucciones solo aparecen en Logística Fletes; en Transfer, Logística Cruces y Rentas ya no salen. El Número Económico muestra solo lo que va antes del espacio y lo que va después se imprime en Placas (por ejemplo, 672243 y PA45396).' },
  { fecha: '2026-10-06', hora: '10:00', version: 'V00426', titulo: 'Tarifario: cuadre con todas las operaciones del cliente', resumen: 'El detalle del tarifario de clientes muestra, además de las operaciones hechas con sus convenios, el total de operaciones del cliente. Si hay diferencia, un enlace lista las operaciones que usan otro convenio y el motivo: convenio borrado, de otro tarifario, no ligado a este tarifario o sin convenio.' },
  { fecha: '2026-10-06', hora: '09:00', version: 'V00425', titulo: 'Relación Tarifario ↔ Convenios corregida', resumen: 'El tarifario y sus convenios ya se relacionan por el número de consecutivo aunque esté guardado como CONV-054, 054 o 54. Con esto el detalle del tarifario muestra las operaciones de cada convenio, y al borrar un convenio su línea se quita del tarifario. Las líneas del tarifario cuyo convenio ya no existe se marcan como Sin convenio y se pueden quitar con un botón. La misma corrección aplica en el tarifario de proveedores.' },
  { fecha: '2026-10-05', hora: '17:30', version: 'V00424', titulo: 'Operaciones por convenio en el detalle del Tarifario de Clientes', resumen: 'El detalle de cada tarifario (pre convenio) muestra la columna Operaciones con cuántas operaciones se han hecho con cada convenio, y al pie el total de operaciones hechas con todos sus convenios. No cuenta las operaciones de prueba.' },
  { fecha: '2026-10-05', hora: '10:30', version: 'V00423', titulo: 'Referencias de Puentes sin el Historial manual', resumen: 'Se quitó la pestaña Historial manual (anterior) de Referencias de Puentes. Quedan Historial de referencias, Operaciones sin asignar, Saldo y Otros Cruces.' },
  { fecha: '2026-10-05', hora: '10:00', version: 'V00422', titulo: 'Pestañas por tipo en Operaciones Activas, Colombia cuadrado y saldo de Diesel por día', resumen: 'Operaciones Activas tiene pestañas Todos, Transfer, Logística Cruces, Logística Fletes y Rentas, cada una con su número de operaciones. En la tarjeta de Puente Colombia la caseta y el puente se descuentan del saldo del puente, igual que en la pestaña Saldo. El saldo de Diesel puede ser general para todos los proveedores y se descuenta el total cargado por día; su detalle muestra cada día con sus referencias y operaciones.' },
  { fecha: '2026-10-03', hora: '11:30', version: 'V00421', titulo: 'Carta de Instrucciones para todos los cruces, configurable y con datos del cliente; Completados más rápido', resumen: 'La Carta de Instrucciones se puede generar en todas las operaciones (Logística Cruces, Transfer, Fletes y Rentas) desde Activas, Completados y Cancelados. Con el botón Carta se configura para todos si se muestra siempre o solo para ciertos tipos de operación o destinos (bodegas). La carta trae la referencia del cliente resaltada, Cliente Paga, Cliente Mercancía, origen donde se engancha, destino donde se entrega, descripción de la mercancía y bultos. Servicios Completados consulta solo el rango de fechas filtrado y ya no tarda.' },
  { fecha: '2026-10-03', hora: '10:00', version: 'V00420', titulo: 'Referencias de puentes solo manuales, Sacar sin error y Colombia en su puente', resumen: 'Ya no se crean referencias de puentes automáticamente: las operaciones marcadas Verde quedan en Operaciones sin asignar y se envían a mano a la referencia que elijas. Sacar y eliminar referencias ya no fallan con Connection failed; el cambio se ve al instante y se sincroniza solo. Las operaciones de aduana Colombia se envían siempre a Puente Colombia, y el detalle de una referencia tiene el botón Sacar las de otro puente para corregir las que ya estaban mezcladas.' },
  { fecha: '2026-10-02', hora: '17:30', version: 'V00419', titulo: 'Carta de Instrucciones y Prueba de Entrega siempre con direcciones y mercancía', resumen: 'La Carta de Instrucciones y la Prueba de Entrega ya no salen a veces con N/A en origen y destino: las empresas, remolques y direcciones se leen directamente de la base de datos al generar el documento si la pantalla aún no los tenía cargados. La Carta de Instrucciones de Servicios Completados y de Cancelados ahora llena las direcciones (antes salían siempre en N/A). La Carta imprime la descripción de la mercancía en la franja amarilla.' },
  { fecha: '2026-10-02', hora: '15:20', version: 'V00418', titulo: 'Saldos de puente por puente: cuadran con el Historial de referencias', resumen: 'El saldo de cada puente descuenta todos sus cobros: Puente III incluye Caseta Puente III y Trompo Puente III, y Puente Colombia incluye la caseta y el Puente Mx Colombia. Así el monto cruzado del Saldo y de las tarjetas de Operaciones Activas es igual al total de las referencias del Historial (por ejemplo, 1,426 en Puente III y 658.80 en Colombia).' },
  { fecha: '2026-10-02', hora: '14:50', version: 'V00417', titulo: 'El detalle de cada saldo de puente muestra solo lo que le descuenta', resumen: 'En el asiento de un saldo de Referencias de Puentes, las operaciones de cada referencia muestran el concepto y el monto que descuentan de ESE saldo (por ejemplo, el saldo de Puente Mx Colombia lleva solo el puente de $90 de cada cruce y la caseta va al saldo de Caseta Mx Colombia), además del total del cruce, para que la suma cuadre con el monto cruzado.' },
  { fecha: '2026-10-02', hora: '14:20', version: 'V00416', titulo: 'Aduana Colombia siempre por Puente Colombia con sus dos cobros', resumen: 'Si la aduana de la tarifa es Colombia, la operación cruza por Puente Colombia y no por Puente III. Al marcar Verde se cobran por separado la caseta de Colombia y el Puente Mx Colombia con los montos de los Gastos Incluidos de esa tarifa (si la tarifa no los trae, se usan los del catálogo). En Referencias de Puentes se agrupan en PTC, se marcan con Debe ser Colombia las que traían otra caseta y Asignar monto del puente las corrige.' },
  { fecha: '2026-10-02', hora: '13:30', version: 'V00415', titulo: 'Referencias de puentes: cambiar el puente, agregar operaciones desde el detalle y elegir la referencia del otro cruce', resumen: 'En Operaciones sin asignar se puede cambiar el puente de cada operación y el monto se actualiza con la tarifa del catálogo (Colombia agrega el Puente Mx Colombia). El detalle de cada referencia tiene el botón Agregar operaciones para sumar operaciones sin asignar del mismo puente. Al registrar un Otro Cruce se elige a qué referencia va, o se crea una nueva; ya no se asigna sola.' },
  { fecha: '2026-10-02', hora: '12:30', version: 'V00414', titulo: 'Eliminar referencias del Historial de puentes', resumen: 'En el Historial de referencias de Referencias de Puentes se pueden seleccionar referencias con casillas y eliminar las seleccionadas o todas a la vez. Al eliminarlas, sus operaciones regresan a Operaciones sin asignar.' },
  { fecha: '2026-10-02', hora: '11:40', version: 'V00413', titulo: 'Referencias de puentes: puente por caseta, sin status, saldos más claros y balance de los tres puentes', resumen: 'El puente de cada operación lo decide la caseta cobrada (Caseta AVI, Caseta Puente III o Colombia), no el convenio, así que ya no se marcan como Otro puente las que sí corresponden. Se quitó el status del Historial de referencias y de su detalle. El detalle de cada saldo es más ancho, con el saldo en verde y las referencias que lo descuentan en rojo. La pestaña Saldo tiene arriba tres tarjetas con el balance de Puente AVI, Puente III y Puente Colombia.' },
  { fecha: '2026-10-02', hora: '11:00', version: 'V00412', titulo: 'Detalle de referencia de puentes: más ancho, sacar operaciones, abrir la operación y sin mezclar puentes', resumen: 'El Detalle de Referencia de Puentes es más ancho. Cada operación tiene el botón Sacar para quitarla de la referencia y regresarla a Operaciones sin asignar. Al hacer clic en la fila se abre el formulario de la operación, como en Operaciones y Servicios Completados. Ya no se mezclan puentes: la aduana Colombia siempre va a PTC con caseta y puente, cada referencia solo acepta operaciones de su puente y las que ya estaban en el puente equivocado se marcan como Otro puente.' },
  { fecha: '2026-10-02', hora: '10:00', version: 'V00411', titulo: 'Resumen del día: TC y Diesel juntos, saldos de puente iguales a Saldo, saldo de Diesel y nuevo diseño', resumen: 'Tipo de cambio y Diesel quedan en una sola tarjeta: el TC se captura una vez al día y el Diesel muestra el costo más bajo capturado hoy y de qué proveedor es, con botón para agregar otro costo. Las tarjetas de puente muestran el mismo saldo restante que la pestaña Saldo de Referencias de Puentes (saldos agregados menos las referencias). Nueva tarjeta Saldo Diesel con el saldo restante por proveedor y las cargas de hoy. Las tarjetas tienen un diseño renovado y del mismo tamaño.' },
  { fecha: '2026-10-02', hora: '09:00', version: 'V00410', titulo: 'Cantidades en las referencias de puentes y tarjetas iguales al Saldo', resumen: 'El detalle de cada referencia de puentes numera las operaciones y muestra al pie cuántas son, cuántas tienen verde y el total por moneda; el Historial de referencias muestra al pie el total de referencias y de operaciones. Las tarjetas de puente de Operaciones Activas usan ahora la misma base que la pestaña Saldo (Historial de referencias más Otros Cruces), así el saldo restante coincide.' },
  { fecha: '2026-10-01', hora: '16:40', version: 'V00409', titulo: 'Completadas hoy por tipo de operación', resumen: 'La tarjeta Completadas hoy de Operaciones Activas muestra cuántas de las operaciones completadas del día son de Logística Cruces, Transfer, Logística Fletes y Renta (y Otros, si hay de algún otro tipo).' },
  { fecha: '2026-10-01', hora: '13:50', version: 'V00408', titulo: 'Botón Actualizar sueldo de Trompo visible siempre', resumen: 'El botón Actualizar sueldo (Trompo = $0) aparece en el formulario de la operación (Operaciones Activas y Servicios Completados) aunque el Sueldo Operador esté bloqueado por Autorizaciones, porque aplica la regla del Trompo y no es una edición libre del sueldo.' },
  { fecha: '2026-10-01', hora: '13:30', version: 'V00407', titulo: 'Guardar flujos de servicios con diagonal en el nombre', resumen: 'El Editor de Flujos ya guarda los flujos de servicios cuyo nombre lleva diagonal, como Rentas (Patio / Equipo). Antes marcaba Invalid document reference al guardar.' },
  { fecha: '2026-10-01', hora: '13:00', version: 'V00406', titulo: 'Trompo: sueldo del operador en $0', resumen: 'Cuando la operación es Trompo, el Sueldo Operador queda en $0; si hace falta pagar un monto, se agrega en Costos Adicionales. Se aplica solo en operaciones nuevas o al cambiar o actualizar el convenio. Las operaciones Trompo ya guardadas con sueldo no cambian solas: muestran el botón Actualizar sueldo (Trompo = $0), que lo pone en cero solo al presionarlo.' },
  { fecha: '2026-10-01', hora: '12:20', version: 'V00405', titulo: 'Reglas de Estatus: el flujo se guarda solo con el Servicio', resumen: 'En el Editor de Flujos, Tráfico y Carga ya son opcionales: solo se pide el Servicio y al menos un paso para Guardar flujo. Un flujo sin tráfico o sin carga aplica como Todos a las operaciones de ese servicio que no tengan un flujo más específico; en la lista aparece Todos.' },
  { fecha: '2026-10-01', hora: '11:30', version: 'V00404', titulo: 'Referencias de Puentes reorganizado: Historial de referencias, Operaciones sin asignar y Saldo', resumen: 'Las pestañas quedan en este orden: Historial de referencias (el antes llamado Historial calculado), Operaciones sin asignar (antes Asignar operaciones, solo con las que no están en el Historial de referencias) y Saldo. Al enviar operaciones seleccionadas se elige la referencia ya creada de su puente y fecha de servicio o se crea una nueva. El monto cruzado del Saldo es la suma del Historial de referencias más los Otros Cruces.' },
  { fecha: '2026-10-01', hora: '10:00', version: 'V00403', titulo: 'Operaciones del Historial calculado fuera de Asignar Operaciones', resumen: 'En Referencias de Puentes, las operaciones que ya entraron a una referencia automática del Historial calculado ya no aparecen en Asignar Operaciones. Si se elimina esa referencia automática, vuelven a aparecer.' },
  { fecha: '2026-10-01', hora: '09:30', version: 'V00402', titulo: 'Historial calculado automático de puentes y operaciones de hoy por defecto', resumen: 'Referencias de Puentes abre en Asignar Operaciones con las operaciones de hoy ya filtradas. Nueva pestaña Historial calculado: cuando una operación de Transfer o Logística con Roelca se marca Verde (MX o USA), se agrega sola a la referencia automática de su puente del día (AVI, PT3 o PTC, misma serie de consecutivos), igual que el Historial de Referencias pero automático. Funciona desde Registrar Movimiento, los botones de siguiente paso y Mis Operaciones, y el botón Recalcular hoy revisa la bitácora del día.' },
  { fecha: '2026-09-30', hora: '19:10', version: 'V00401', titulo: 'Convenio visible al generar la referencia de puentes', resumen: 'En Referencias de Puentes, la tabla de operaciones seleccionadas de Generar Referencia muestra el convenio de cada operación (por ejemplo, Cruce de Exportación - Caja - Cargado - 240 Nuevo Laredo). También aparece en las operaciones que se despliegan en el detalle de los saldos. El formulario es más ancho para que quepa.' },
  { fecha: '2026-09-30', hora: '12:00', version: 'V00400', titulo: 'Saldos de Diesel en Referencias del Diesel', resumen: 'Nueva pestaña Saldos en Referencias del Diesel para agregar el saldo inicial por proveedor de diesel con fecha, hora, proveedor, monto y moneda. Cada saldo se descuenta con las referencias del Historial de ese proveedor (galones cargados por costo) y muestra cargas, galones, monto cargado, balance y cuántos galones alcanza al costo vigente. Al hacer clic se abre el asiento contable con cada referencia descontada, y al pulsar una referencia se ven sus operaciones.' },
  { fecha: '2026-09-30', hora: '11:10', version: 'V00399', titulo: 'Referencias de Puentes: selección visible, fecha y hora, y saldos por referencias', resumen: 'Generar Referencia muestra la tabla de las operaciones seleccionadas por puente, ya no pide status y pide fecha y hora. Asignar Operaciones muestra solo las operaciones sin referencia: al generarla pasan al Historial y, si se borra la referencia, regresan. En Agregar Saldo el monto cruzado es la suma de las referencias del Historial de ese puente, y el detalle del saldo muestra ese historial; al pulsar una referencia se ven sus operaciones.' },
  { fecha: '2026-09-30', hora: '10:15', version: 'V00398', titulo: 'Tarjetas de puente con lo de hoy y hora al actualizar el saldo', resumen: 'Las tarjetas de puente de Operaciones Activas muestran solo lo del día: saldo al iniciar hoy, recargas de hoy, cruces de hoy y consumido de hoy, tomando la fecha de servicio de las operaciones; el saldo restante sigue siendo el real. La lista de cruces que se abre desde la tarjeta muestra solo los de hoy. Al actualizar el saldo se piden la fecha y la hora de la actualización, también en Saldos de Puentes. El día se calcula con la fecha local.' },
  { fecha: '2026-09-30', hora: '09:30', version: 'V00397', titulo: 'Saldos de puente con cruces, balance y asiento contable', resumen: 'En Referencias de Puentes, pestaña Agregar Saldo, cada saldo muestra la cantidad de cruces que le descuentan, el monto cruzado, el balance y para cuántos cruces alcanza según la tarifa del puente. Al hacer clic en la fila se abre el asiento del saldo: el abono inicial y cada cruce descontado (operaciones y otros cruces) con su referencia, cargo y saldo corrido.' },
  { fecha: '2026-09-29', hora: '18:40', version: 'V00396', titulo: 'Pestaña Agregar Saldo y usuario automático en Otros Cruces', resumen: 'Referencias de Puentes tiene la pestaña Agregar Saldo con fecha, hora, puente y saldo inicial, tanto en la tabla como en el formulario; ese saldo es el que muestran las tarjetas de Operaciones Activas y se descuenta con los cruces de las operaciones de ese puente. En Otros Cruces, el usuario que registra se guarda automáticamente y ya no aparece en el formulario; se ve en el detalle del cruce.' },
  { fecha: '2026-09-29', hora: '18:00', version: 'V00395', titulo: 'Otros Cruces en Referencias de Puentes', resumen: 'Nueva pestaña Otros Cruces en Referencias de Puentes para registrar cruces que no son de una operación, como carros particulares: fecha, hora, puente, monto, unidad y usuario que registra. Cada cruce toma el consecutivo de su puente (AVI, PT3 o PTC, en la misma serie que las referencias), pasa de inmediato al Historial y descuenta del saldo del puente en Saldos de Puentes y en las tarjetas de Operaciones Activas.' },
  { fecha: '2026-09-29', hora: '17:10', version: 'V00394', titulo: 'Hora del verde corregida y referencias de puentes por puente', resumen: 'En Asignar Operaciones de Referencias de Puentes la columna Hora (Verde) ya muestra la hora en que se marcó Verde MX o Verde USA, en formato 12 horas como en la bitácora. Generar Referencia crea una referencia por puente con consecutivo propio: AVI-DDMMAA-001 para Puente AVI, PT3-DDMMAA-001 para Puente III y PTC-DDMMAA-001 para Colombia (caseta más puente). El Historial muestra # de referencia, puente, fecha y hora de generación, las referencias seleccionadas y el total a pagar por puente.' },
  { fecha: '2026-09-29', hora: '16:20', version: 'V00393', titulo: 'Referencias de Puentes: solo importación y exportación, y hora del verde', resumen: 'Asignar Operaciones de Referencias de Puentes muestra solo operaciones de Importación y Exportación de Transfer y de Logística con proveedor Roelca (sin movimientos ni Fletes). Nueva columna Hora (Verde) con la hora en que se marcó Verde MX o Verde USA, tomada de la bitácora de estatus; se puede ordenar por ella y sale en el Excel.' },
  { fecha: '2026-09-29', hora: '15:10', version: 'V00392', titulo: 'Control de puentes en las tarjetas y nueva Asignar Operaciones de Referencias de Puentes', resumen: 'Las tarjetas Puente AVI, Puente III y Puente Colombia muestran el saldo agregado, la cantidad de cruces, el total consumido por esos cruces y el saldo restante (Colombia separa caseta y puente); al pulsar los cruces se ve el detalle. En Referencias de Puentes, Asignar Operaciones muestra solo Transfer y Logística con proveedor Roelca, con casilla para seleccionar todas, filtros por Fecha, Puente y Unidad, y las columnas Ref. Operación, Fecha del Servicio, Unidad, Convenio, Puente y Monto (Colombia con caseta y puente). El botón Asignar monto del puente pone el monto correcto a las operaciones que no lo tienen, incluidas caseta y puente en Colombia.' },
  { fecha: '2026-09-29', hora: '12:20', version: 'V00391', titulo: 'Tarjetas del resumen del día con un solo diseño', resumen: 'Las siete tarjetas del resumen de Operaciones Activas tienen ahora el mismo tamaño y el mismo diseño: etiqueta arriba, cifra principal grande, detalle debajo y botón al pie, con una franja de color por tarjeta y sin emojis. Completadas hoy muestra una barra de avance. Las tarjetas de puente muestran el saldo disponible como cifra principal, lo gastado hoy con su número de cruces (Colombia separa caseta y puente) y el botón Actualizar saldo.' },
  { fecha: '2026-09-29', hora: '11:40', version: 'V00390', titulo: 'El documento adjuntado al generar la factura ya aparece en el historial', resumen: 'En Facturación de Clientes y Proveedores, el documento que se adjunta en Generar Factura ya aparece en el Historial de Facturas en cuanto se confirma, sin tener que cargarlo de nuevo. El historial guardado en la sesión se mantiene al día con cada cambio (facturas nuevas, documentos subidos, estatus), así al volver al módulo no se ve una versión vieja. En el formulario, la tarjeta del documento ocupa todo el ancho.' },
  { fecha: '2026-09-29', hora: '10:30', version: 'V00389', titulo: 'Tres tarjetas de puente y proveedor por nombre corto', resumen: 'En el resumen del día de Operaciones Activas se quitó la tarjeta Canceladas hoy y ahora hay tres tarjetas de puente: Puente AVI, Puente III y Puente Colombia, cada una con lo gastado hoy, el número de cruces, el saldo disponible y su botón para actualizar saldo; Puente Colombia muestra por separado la caseta y el puente (Puente Mx Colombia). En el formulario, el buscador de Proveedor de Transporte muestra el nombre corto con la razón social debajo y, al elegirlo, queda la razón social.' },
  { fecha: '2026-09-28', hora: '12:40', version: 'V00388', titulo: 'Aduana Colombia con dos cobros de puente, aduana visible y subtotal a 2 decimales', resumen: 'Las operaciones con aduana Colombia descuentan dos cobros: la caseta de la tarifa (Caseta Mx Colombia, o Trompo Colombia si es trompo) y el piso del puente, Puente Mx Colombia, con el monto fijo del catálogo Tipos de Gastos ($90 mientras no se cambie). Nuevo Laredo sigue con un solo cobro. En Tarifas de Referencia, Colombia admite una caseta más el Puente Mx Colombia. Saldos de Puentes, su reporte, la tarjeta de casetas, la utilidad y Servicios Completados incluyen el piso. La aduana aparece en las opciones de convenio y en el resumen de la operación, y el subtotal convertido se muestra a 2 decimales.' },
  { fecha: '2026-09-28', hora: '11:30', version: 'V00387', titulo: 'Movimiento en Falso paga la mitad del sueldo', resumen: 'Cuando una operación llega a un estatus Falso, el Sueldo Operador se divide a la mitad (por ejemplo, 400 pasa a 200) y el Sueldo Total se recalcula. Aplica desde el formulario, Registrar Movimiento, los botones de siguiente paso (Activas, Completados y Cancelados) y Mis Operaciones. Si la operación sale de Falso se restaura el sueldo completo, y nunca se divide dos veces.' },
  { fecha: '2026-09-28', hora: '09:10', version: 'V00386', titulo: 'Cambiar o actualizar el convenio trae todo lo ligado', resumen: 'Al cambiar el convenio de una operación, también si ya estaba guardada, se traen el monto y la moneda, el sueldo del operador, el combustible, el tipo de servicio, el tráfico y la carga del nuevo convenio. El botón Actualizar monto ahora es Actualizar convenio: muestra qué va a cambiar y trae todos esos datos vigentes aunque el convenio sea el mismo.' },
  { fecha: '2026-09-27', hora: '08:30', version: 'V00385', titulo: 'Formularios configurables: obligatorios, visibilidad por rol y editor', resumen: 'Autorizaciones ahora maneja, por módulo, qué campos del formulario son obligatorios, cuáles se ocultan y qué roles los ven; los campos aparecen solos al abrir cada formulario. Todos los formularios (Operaciones, Empresas, Contactos, Direcciones, Unidades, Remolques, Colaboradores, Convenios, MTTO, Combustible, Tipo de Cambio, Costos Adicionales, Deducciones, Nómina, Puentes, Diésel, Facturación, Catálogos y Usuarios) tienen el botón Editar formulario para renombrar, mover, ocultar y marcar obligatorios sus campos; el botón lo ve solo el Admin y se habilita a otros roles con el permiso Editar Formularios en Roles y Permisos.' },
  { fecha: '2026-09-27', hora: '07:00', version: 'V00384', titulo: 'Siguiente paso pide fecha y hora; ficha sin Proveedores en flota propia', resumen: 'Al presionar un botón de Siguiente Paso en la ficha de la operación (Activas y Cancelados) se abre Registrar Movimiento con la fecha y hora actuales precargadas para confirmarlas o cambiarlas; el movimiento, sus pasos automáticos y el cruce del puente quedan con esa fecha. En Transfer y en Logística de Cruces con proveedor Roelca, la pestaña Unidad y Operador de la ficha (Activas y Completados) ya no muestra la parte de Proveedores.' },
  { fecha: '2026-09-27', hora: '06:20', version: 'V00383', titulo: 'Empresas: una sola razón social, una sola dirección y Borrar con autorización', resumen: 'El formulario de Empresas tiene un solo campo de Razón Social (se guarda igual para operaciones, facturación y pagos) y una sola sección de dirección, la del tipo de empresa seleccionado (Cliente (Paga) es la principal); las direcciones generales viejas se muestran ahí para no perderse. La regla Borrar de Autorizaciones ahora se respeta al eliminar o unir empresas, y también en Operaciones, Unidades, Contactos, Colaboradores, Combustible, Convenios y Proveedores/Unidades de Proveedor.' },
  { fecha: '2026-09-27', hora: '05:30', version: 'V00382', titulo: 'Autorizaciones solo piden permiso por lo que realmente cambió', resumen: 'Al guardar, las autorizaciones ya no bloquean campos que el usuario no tocó: se compara cada campo contra su valor anterior sin distinguir 0 de vacío, 1500 de 1500.00, formatos de fecha, mayúsculas ni acentos; Unidades, Remolques, Colaboradores, Direcciones, Contactos, Convenios, MTTO, Proveedores de Unidad y los Tarifarios dejaron de mandar todos sus campos como modificados; en Operaciones no cuentan el Status que mueve el flujo ni los montos que se recalculan solos; los Usuarios exentos y los accesos temporales aprobados ya se respetan al guardar, y Agregar libre funciona en Operaciones.' },
  { fecha: '2026-09-27', hora: '04:30', version: 'V00381', titulo: 'Control de saldos de puentes y documentos de factura visibles', resumen: 'Saldos de Puentes rediseñado sin íconos y con letras más legibles: resumen por moneda (disponible, recargado, consumido, hoy), tabla de control por puente con estado y cuántos cruces alcanzan, y libro con filtros por fecha y tipo, totales y Excel. En Facturación de Clientes y Proveedores el documento de la factura se muestra en una tarjeta grande (cargado, listo para subir o sin documento) en la ficha y en los formularios, la fila indica Doc ✓ / Sin doc, y un clic en la fila abre la ficha.' },
  { fecha: '2026-09-27', hora: '03:30', version: 'V00380', titulo: 'Operaciones de prueba', resumen: 'Nuevo botón 🧪 Prueba en el formulario de una operación nueva: su referencia lleva PR. (PR.TR-270926-001) con su propio consecutivo y se trabaja como una operación real en Activas, Completados y Cancelados, pero no entra a Facturación, Pagos, Nómina, Estadísticas, Reportes, Panel de Control, Saldos de Puentes, auditorías ni exportaciones a Excel.' },
  { fecha: '2026-09-27', hora: '02:40', version: 'V00379', titulo: 'Registrar Movimiento encuentra la regla de Logística Fletes', resumen: 'Las operaciones de servicios con nombre de varias palabras (como Logistica Fletes) y carga Cargado/Vacio ya encuentran su flujo en Reglas de Estatus: la búsqueda compara Servicio, Tráfico y Carga sin distinguir mayúsculas ni acentos, igual que el formulario.' },
  { fecha: '2026-09-27', hora: '02:20', version: 'V00378', titulo: 'Registrar Movimiento estricto a la regla', resumen: 'El desplegable de Registrar Movimiento ofrece únicamente los estatus del flujo de esa operación — sin lista completa de respaldo; si la combinación no tiene flujo configurado, el registro queda deshabilitado con un aviso, y el guardado valida que el estatus pertenezca a la regla.' },
  { fecha: '2026-09-27', hora: '01:40', version: 'V00377', titulo: 'La regla de estatus decide dónde se descuenta el puente', resumen: 'En el editor de Reglas de Estatus cada paso tiene la casilla "Aquí se descuenta el puente": al marcar ese estatus en la operación se cobra el peaje (los verdes solo aplican si la regla no define ninguno); y Registrar Movimiento ahora ofrece únicamente los estatus del flujo que corresponde a esa operación.' },
  { fecha: '2026-09-26', hora: '15:10', version: 'V00376', titulo: 'Sin validación del Verde para completar', resumen: 'Se quitó la validación que exigía marcar Verde MX o Verde USA antes de poner Servicio Completado: cualquier operación se puede completar desde la ficha, el registro manual o el formulario; el peaje se sigue descontando al marcar Verde (o al completar como respaldo) y la alerta informativa de la fila se mantiene.' },
  { fecha: '2026-09-26', hora: '14:30', version: 'V00375', titulo: 'Movimientos sin regla del Verde y el verde de la bitácora cuenta', resumen: 'Los movimientos ya no piden Verde para completar aunque el tipo diga Transfer (se detectan también por el convenio, y no cobran peaje); y una operación con Verde MX o USA en su bitácora siempre puede marcarse como Servicio Completado, aunque el verde haya entrado por transición automática.' },
  { fecha: '2026-09-26', hora: '01:30', version: 'V00374', titulo: 'Gasto de puente controlado en Tarifas de Referencia', resumen: 'Al agregar un gasto a una tarifa, elegir el puente precarga el monto del catálogo; las tarifas con aduana solo aceptan UN gasto de puente (aviso al intentar otro); y la tabla marca en ámbar las tarifas con aduana sin gasto de puente y en rojo las que tienen más de uno.' },
  { fecha: '2026-09-26', hora: '00:40', version: 'V00373', titulo: 'La caseta de los Gastos Incluidos manda en el peaje', resumen: 'Al cobrar el saldo del puente se usa la caseta agregada en los Gastos Incluidos de la tarifa de la operación, con su monto (por ejemplo Caseta Puente III $144); si la tarifa no trae caseta, se cobra el puente que corresponde al tráfico como hasta ahora.' },
  { fecha: '2026-09-25', hora: '23:59', version: 'V00372', titulo: 'El candado del Verde solo al completar', resumen: 'El candado del Verde aplica únicamente al cambiar el status a Servicio Completado: editar sueldos, gastos o cualquier otro dato guarda normal; y si la operación ya estaba completada sin verde, sale el recordatorio de marcar Verde para descontar el saldo del puente, sin impedir el guardado.' },
  { fecha: '2026-09-25', hora: '23:20', version: 'V00371', titulo: 'Sin Verde no se completa', resumen: 'Las operaciones que cruzan puente (Transfer y Logística de Cruces con Roelca) ya no se pueden marcar como Servicio Completado sin haber registrado antes Verde MX o Verde USA — un aviso lo explica en la ficha, el registro manual y el formulario; Fletes y Movimientos quedan exentos.' },
  { fecha: '2026-09-25', hora: '22:40', version: 'V00370', titulo: 'Registrar Status de vuelta en la ficha de Operaciones', resumen: 'El botón Registrar Status regresa al Detalle de Operación de Operaciones Activas (y sigue cobrando el peaje al registrar un Verde); en Servicios Completados permanece fuera.' },
  { fecha: '2026-09-25', hora: '22:00', version: 'V00369', titulo: 'Reporte de saldos del puente y regla de aplicación', resumen: 'Nuevo reporte en Saldos de Puentes con todas las operaciones que cruzan (Transfer y Logística de Cruces con Roelca): fecha de servicio, tipo, tráfico, puente y saldo descontado o Sin descuento, con rango de fechas, totales por moneda y Excel; el descuento del peaje respeta la misma regla en todos los caminos y Logística de Fletes nunca cobra.' },
  { fecha: '2026-09-25', hora: '21:00', version: 'V00368', titulo: 'Saldos de Puentes como libro contable', resumen: 'El módulo se ve ahora como asientos contables: chips con el disponible de cada puente y un libro con abonos (recargas), cargos (cruces) y la columna Saldo que siempre dice cuánto queda; y la ficha de Operaciones ya no muestra el botón Registrar Status.' },
  { fecha: '2026-09-25', hora: '20:00', version: 'V00367', titulo: 'Cobro del peaje en todos los caminos del Verde', resumen: 'El peaje se descuenta al marcar Verde MX o Verde USA también desde el registro manual de horarios y al guardar el formulario en verde; las filas de Operaciones muestran alerta cuando el cruce aún no descuenta su saldo; y el historial de movimientos ya no enseña el saldo corrido.' },
  { fecha: '2026-09-25', hora: '19:15', version: 'V00366', titulo: 'El gastado de hoy solo suma cruces de hoy', resumen: 'Los cruces cobrados por el respaldo de Completado llevan la fecha de servicio de la operación (no la del día en que se registró), así el gastado de hoy solo suma los verdes marcados hoy; el botón Aplicar a operaciones ahora también corrige las fechas de los cruces ya cobrados.' },
  { fecha: '2026-09-25', hora: '18:30', version: 'V00365', titulo: 'Cruces más anchos, peaje por tráfico y ficha de Completados limpia', resumen: 'El modal de cruces del día es más ancho y las referencias no se parten; al marcar cualquier Verde el peaje se cobra del puente que corresponde al tráfico (importación AVI en dólares, exportación Puente III en pesos); y la ficha de Servicios Completados ya no muestra Registrar Status.' },
  { fecha: '2026-09-25', hora: '17:30', version: 'V00364', titulo: 'Bódegas sin alerta, bitácora en Completados y permisos nuevos', resumen: 'Las bódegas ya no muestran la alerta de Origen/Destino sin documentos; la Bitácora de Servicios Completados enseña el estatus marcado de cada movimiento; la tarjeta Caseta/Puente del formulario aparece solo al marcar Verde MX o USA; y Roles ya lista Saldos de Puentes y la casilla Personalizar Vista (Operaciones).' },
  { fecha: '2026-09-25', hora: '16:00', version: 'V00363', titulo: 'Status visible en los cruces del día', resumen: 'El modal de Casetas del día muestra ahora el status de cada operación que suma al saldo y con qué marca se cobró el peaje (Verde MX, Verde USA o Completado) — el descuento solo ocurre en esas marcas, nunca en un Documentado.' },
  { fecha: '2026-09-25', hora: '15:10', version: 'V00362', titulo: 'Cruces del día al hacer clic en Casetas', resumen: 'Al hacer clic en el gastado de hoy (dólares o pesos) de la tarjeta Casetas del día se abre la lista de operaciones que suman al saldo: referencia, puente y peaje de cada cruce, con el total del día.' },
  { fecha: '2026-09-25', hora: '14:30', version: 'V00361', titulo: 'Agregar saldo con puente desplegable', resumen: 'En Saldos de Puentes el saldo se agrega desde un solo botón arriba, con el puente elegido en lista desplegable (moneda no editable, saldo pendiente y total en vivo); las tarjetas de cada puente quedan solo informativas, con su botón de historial.' },
  { fecha: '2026-09-25', hora: '13:30', version: 'V00360', titulo: 'Peaje al marcar Verde y gasto del día en la tarjeta', resumen: 'El peaje se descuenta al marcar Verde MX (exportación, Puente III en pesos) o Verde USA (importación, Caseta AVI en dólares) en los horarios; la tarjeta de Operaciones muestra lo gastado hoy en cruces en dólares y en pesos, y su botón Actualizar saldo abre el modal con puente (lista del catálogo), moneda, saldo a agregar, saldo pendiente por puente y total.' },
  { fecha: '2026-09-25', hora: '12:00', version: 'V00359', titulo: 'Saldo disponible por moneda e historial de deducciones', resumen: 'Saldos de Puentes muestra arriba el saldo disponible en dólares y en pesos; al presionarlos (o el 📜 de cada puente) se abre el historial por fechas de deducciones y recargas con el saldo corrido. El modal de recarga de Operaciones ahora muestra fecha, moneda, saldo a agregar, saldo restante y total por puente.' },
  { fecha: '2026-09-25', hora: '10:30', version: 'V00358', titulo: 'Cuentas de puentes: saldo inicial, cruces y saldo actual', resumen: 'Saldos de Puentes funciona ahora como cuenta por puente: Agregar saldo suma recargas (fecha de hoy y moneda fijas, con saldo restante y total en el modal), cada operación completada descuenta su cruce, y el saldo actual se marca en amarillo o rojo al ir quedando bajo — en el módulo y en la tarjeta del resumen.' },
  { fecha: '2026-09-24', hora: '12:00', version: 'V00357', titulo: 'Utilidad Transfer en la ficha y saldo de puente retroactivo', resumen: 'La ficha de la operación muestra la UTILIDAD cuando es Transfer (generado − saldo del puente − gastos adicionales − sueldo del proveedor, con desglose y pesos convertidos con el TC de la operación), y Saldos de Puentes trae el botón Aplicar a operaciones para colocar el saldo del puente a todas las completadas que no lo tenían.' },
  { fecha: '2026-09-24', hora: '13:00', version: 'V00356', titulo: 'Utilidad de Transfer con puente y gastos, y saldos masivos', resumen: 'En Transfer, la Utilidad Estimada resta ahora el saldo del puente y los gastos además del proveedor (todo en MXN con el TC de la operación); y el botón Saldos de puentes de Servicios Completados coloca el saldo a todas las completadas que no lo tenían.' },
  { fecha: '2026-09-24', hora: '10:30', version: 'V00355', titulo: 'Tarifa del puente al completar el servicio', resumen: 'Al marcar Servicio Completado, la operación guarda la tarifa del puente del día: Importación toma el saldo de Caseta AVI y Exportación el de Caseta Puente III. Además la moneda queda marcada con su color en Saldos de Puentes y la tarjeta avisa si falta la captura de hoy.' },
  { fecha: '2026-09-23', hora: '21:40', version: 'V00354', titulo: 'Cliente (Mercancía) con razón social', resumen: 'El buscador de Cliente (Mercancía) del formulario muestra y guarda la razón social de la empresa (no el nombre corto), y con ello la razón social aparece en la operación y en todos los documentos.' },
  { fecha: '2026-09-23', hora: '21:00', version: 'V00353', titulo: 'Razón social en los documentos generados', resumen: 'Los documentos de la operación (Solicitud de Retiro, Check List, Instrucciones de Servicio y demás) muestran ahora la RAZÓN SOCIAL de los clientes y proveedores — el cliente de la mercancía incluido — tomada de la ficha de la empresa.' },
  { fecha: '2026-09-23', hora: '20:00', version: 'V00352', titulo: 'Saldo precargado al elegir el puente y captura una vez al día', resumen: 'Al elegir el puente en Saldos de Puentes, el saldo se precarga con el monto del catálogo; y la captura desde la tarjeta de Operaciones guarda en la tabla con la fecha del momento y el botón se oculta cuando el día ya quedó registrado.' },
  { fecha: '2026-09-23', hora: '19:30', version: 'V00351', titulo: 'El registro de saldos de puentes abre en modal', resumen: 'En Saldos de Puentes, el botón Registrar saldo (y el editar de cada fila) abre ahora un modal con la fecha, el puente y el saldo, en vez del formulario en el encabezado.' },
  { fecha: '2026-09-23', hora: '19:00', version: 'V00350', titulo: 'Módulo Saldos de Puentes (Bases de Datos)', resumen: 'Nuevo módulo en Bases de Datos para registrar cada día el saldo de los puentes: fecha, puente (relacionado con el catálogo Tipos de Gastos) y saldo. La tarjeta Casetas del día también alimenta esta tabla, y el saldo más reciente actualiza el catálogo para toda la app.' },
  { fecha: '2026-09-23', hora: '18:10', version: 'V00349', titulo: 'Casetas del día en el resumen, con captura de saldos', resumen: 'La tarjeta Casetas del día ya aparece en el resumen junto al diésel, con el saldo vigente del Puente AVI y del Puente III, y su botón + Actualizar saldos abre la captura (como el tipo de cambio): lo guardado va al catálogo Tipos de Gastos y se refleja en toda la app al momento.' },
  { fecha: '2026-09-23', hora: '17:30', version: 'V00348', titulo: 'Casetas del día en el resumen', resumen: 'El resumen del día muestra ahora la tarjeta Casetas del día con el saldo vigente del Puente AVI y del Puente III, tomado en vivo del catálogo Tipos de Gastos: al editar el importe ahí, la tarjeta se actualiza al momento.' },
  { fecha: '2026-09-23', hora: '16:45', version: 'V00347', titulo: 'Convenios sin prefijo de ningún tipo', resumen: 'El botón Quitar CONV- ahora también elimina el número inicial que quedaba en algunos nombres de convenio ("285 - Cruce…" queda "Cruce…"), en operaciones y en los detalles de convenios de clientes y proveedores. Vuelve a presionarlo una vez.' },
  { fecha: '2026-09-23', hora: '16:00', version: 'V00346', titulo: 'Convenios sin el prefijo CONV-', resumen: 'Los convenios de clientes y proveedores ya no llevan el prefijo CONV-: los nuevos nacen solo con su número, y el botón Quitar CONV- de Detalles del Convenio se lo quita a todos los registrados (convenios y operaciones), conservando los números.' },
  { fecha: '2026-09-23', hora: '15:00', version: 'V00345', titulo: 'Los documentos de la operación abren en su modal', resumen: 'El botón Ver documentos de la ficha abre ahora un modal centrado con todos los documentos de la operación, cada uno con su botón Ver/Descargar.' },
  { fecha: '2026-09-23', hora: '14:30', version: 'V00344', titulo: 'Ver documentos en la ficha, editar la vista y Manual del módulo', resumen: 'La ficha de la operación tiene el botón Ver documentos con TODO lo subido (Carta Porte, DODA, Entry\'s, Manifiesto y más); el botón ✎ Vista permite ocultar/mostrar los botones agregados (guardado para todos); y el botón 📖 Manual abre la guía del módulo en otra pestaña.' },
  { fecha: '2026-09-23', hora: '13:20', version: 'V00343', titulo: 'Razón Social de la empresa en toda la cadena', resumen: 'La empresa tiene ahora el campo Razón Social: captúralo (ej. en Caro-Kar Pesos pon Caro-Kar Transportes), presiona el botón Razón social de Empresas y todas las operaciones, facturas y pagos mostrarán ese nombre.' },
  { fecha: '2026-09-23', hora: '12:30', version: 'V00342', titulo: 'Moneda visible al editar la empresa + razón social en toda la cadena', resumen: 'La moneda y el tipo de factura de la empresa aparecen de inmediato al editar (aunque estén guardados con el nombre viejo), y el nuevo botón Razón social escribe el nombre actual de todas las empresas en operaciones, facturación y pagos.' },
  { fecha: '2026-09-23', hora: '10:00', version: 'V00341', titulo: 'Los documentos de la operación ya se consultan', resumen: 'Los PDF que subes a una operación (Carta Porte, DODA, Entry\'s, etc.) ahora se ven donde los necesitas: en la pestaña Pedimento del formulario aparece la lista de documentos guardados, y el detalle de la operación en la auditoría también los muestra.' },
  { fecha: '2026-09-22', hora: '18:20', version: 'V00340', titulo: 'Auditar operaciones desde Estadísticas + Excel con configuraciones', resumen: 'En el reporte de operaciones de Estadísticas cada fila trae ver detalle y editar (el cambio se refleja al momento), y el Excel abre primero el selector de columnas con configuraciones guardadas con nombre.' },
  { fecha: '2026-09-22', hora: '17:00', version: 'V00339', titulo: 'Estadísticas EN VIVO', resumen: 'Las estadísticas quedaron suscritas a la base: cualquier cambio en operaciones, facturación o pagos se refleja al momento, sin volver a presionar Buscar — los números siempre coinciden con lo que muestra el resto de la app.' },
  { fecha: '2026-09-22', hora: '16:10', version: 'V00338', titulo: 'Configuraciones del Excel con nombre (Servicios Completados)', resumen: 'Al exportar a Excel primero se muestran las configuraciones guardadas: eliges una y arma el Excel con sus columnas, o creas una nueva, le pones nombre y queda guardada para todos.' },
  { fecha: '2026-09-22', hora: '09:30', version: 'V00337', titulo: 'Reportes "todos excepto" y minimizado informativo', resumen: 'En Reportes ya puedes incluir todos los estatus EXCEPTO los que marques; y al minimizar una operación, la pastilla muestra la referencia, el cliente, el remolque, la fecha de servicio y el tipo de operación.' },
  { fecha: '2026-09-21', hora: '20:10', version: 'V00335', titulo: 'Rango de fechas y moneda en la auditoría por empresa', resumen: 'La auditoría de la empresa ahora filtra las operaciones por rango de fecha de servicio y muestra la moneda configurada en la ficha de la empresa.' },
  { fecha: '2026-09-21', hora: '19:20', version: 'V00334', titulo: 'Auditoría de la cadena por EMPRESA', resumen: 'Desde la ficha de cualquier empresa (botón 🔍) se ve toda su cadena en vivo — operaciones, facturación y pagos — separada por su papel: Cliente que Paga, Cliente de Mercancía o Proveedor de transporte y servicios.' },
  { fecha: '2026-09-21', hora: '18:40', version: 'V00332', titulo: 'Combustible y Catálogos bajo Autorizaciones', resumen: 'Se integraron Combustible y Catálogos al módulo de Autorizaciones: en Combustible se controlan sus campos y acciones, y en Catálogos quién puede crear, editar o borrar registros de cualquier catálogo.' },
  { fecha: '2026-09-21', hora: '17:05', version: 'V00331', titulo: 'La autorización solo mira lo que tú tocas', resumen: 'Al guardar una empresa, la autorización se revisa únicamente sobre los campos que el usuario realmente modificó; lo que el formulario recalcula solo ya no dispara avisos ni afecta a los demás campos.' },
  { fecha: '2026-09-21', hora: '16:45', version: 'V00330', titulo: 'El historial de cambios se llena solo', resumen: 'Cada actualización de la app queda registrada automáticamente en el Historial de Cambios, con fecha, versión y su explicación — ya no hay que capturarla a mano.' },
  { fecha: '2026-09-21', version: 'V00329', titulo: 'Módulo Historial de Cambios + escritura corregida en Empresas', resumen: 'Se estrenó el módulo Historial de Cambios para la gerencia (con informe copiable para WhatsApp) y se corrigió que algunos campos de Empresas perdieran el cursor al escribir.' },
  { fecha: '2026-09-21', version: 'V00328', titulo: 'Autorización solo si de verdad se modificó', resumen: 'Al guardar una empresa ya no pide autorización por campos que nadie tocó; solo por lo que sí se cambió.' },
  { fecha: '2026-09-21', version: 'V00327', titulo: 'Los campos protegidos se ven bloqueados', resumen: 'En Empresas, los campos que requieren autorización aparecen atenuados con candado 🔒; al darles clic se solicita el acceso temporal.' },
  { fecha: '2026-09-21', version: 'V00326', titulo: 'Regla "Agregar libre" en Autorizaciones', resumen: 'Ahora un campo protegido puede capturarse libremente la PRIMERA vez (ej. la Moneda al crear la empresa) y quedar bloqueado para cambios posteriores.' },
  { fecha: '2026-09-21', version: 'V00325', titulo: 'Reporte de Vencimiento bajo Autorizaciones', resumen: 'Cambiar documentos o fechas del Reporte de Vencimiento ya no es libre: si el usuario no está autorizado, el cambio se convierte en una solicitud que un Admin aprueba.' },
  { fecha: '2026-09-20', version: 'V00324', titulo: 'Auditoría: rango de fechas, edición al frente y detalle legible', resumen: 'La auditoría filtra las operaciones por fecha de servicio, el formulario de edición abre al frente (y la auditoría te espera donde ibas) y el ojito muestra el detalle con nombres, no claves.' },
  { fecha: '2026-09-20', version: 'V00323', titulo: 'Auditoría más grande, con ✓ Revisado y caminos', resumen: 'La auditoría ocupa el 80% de la pantalla; cada pieza tiene botón ✓ Revisado (los revisados se van al final, los problemas al inicio) y al hacer clic en una operación, factura o pago se muestra SOLO su camino.' },
  { fecha: '2026-09-19', version: 'V00322', titulo: 'Auditoría en vivo, con detalle y edición', resumen: 'La auditoría quedó conectada en vivo: cualquier corrección se refleja al momento; cada pieza tiene ver detalle y editar, se resaltan los problemas y las monedas que no concuerdan.' },
  { fecha: '2026-09-19', version: 'V00320', titulo: 'Auditoría en tres columnas con monedas', resumen: 'La auditoría se ve en tres columnas (Operaciones, Facturación, Pagos) con las monedas de cada pieza a la vista y el camino de cada operación iluminado.' },
  { fecha: '2026-09-19', version: 'V00319', titulo: 'La auditoría busca solo clientes que pagan', resumen: 'El buscador de la auditoría ya no lista todas las empresas: solo los clientes que pagan.' },
  { fecha: '2026-09-19', version: 'V00318', titulo: 'Nueva Auditoría de la cadena por cliente', resumen: 'Se estrenó la auditoría que cruza operaciones, facturas y pagos de un cliente: detecta operaciones que cambiaron después de facturarse, sin facturar, dobles cobros y pagos descuadrados, con Excel del reporte.' },
  { fecha: '2026-09-19', version: 'V00317', titulo: 'Reparar nombres con CONV + Excel completo por empresa', resumen: 'Botón para limpiar los nombres que traían el "CONV-###" incrustado, y descarga de un Excel por empresa con sus operaciones, facturación y pagos en tres hojas.' },
  { fecha: '2026-09-18', version: 'V00316', titulo: 'Los módulos ya no se desordenan al recargar', resumen: 'Se corrigió que la app se viera desacomodada al recargar justo después de publicarse una actualización.' },
  { fecha: '2026-09-18', version: 'V00315', titulo: 'Unir duplicados con toda la información', resumen: 'Al unir registros duplicados de empresas se ve la ficha de cada candidato (tipos, RFC, status, fecha de alta y operaciones) antes de decidir cuál queda.' },
  { fecha: '2026-09-18', version: 'V00314', titulo: 'Nombres de convenio limpios y clientes bien distinguidos', resumen: 'Los convenios ya no muestran el "CONV-###" en el nombre y el buscador de Cliente (Paga) distingue empresas con el mismo nombre.' },
  { fecha: '2026-09-18', version: 'V00313', titulo: 'Tarifas A/B y catálogos en vivo en operaciones', resumen: 'El modal de operaciones muestra el número de tarifario correcto, deja elegir Tarifa A o B en convenios con dos montos, y los convenios y tarifarios se actualizan en vivo mientras el formulario está abierto.' },
  { fecha: '2026-09-17', version: 'V00312', titulo: 'Abrir en pestaña nueva con filtros + tablas más ágiles', resumen: 'Convenios, tarifarios y cancelados abren en pestaña nueva conservando los filtros; las tablas grandes cargan por partes y las barras de desplazamiento siempre se ven.' },
  { fecha: '2026-09-17', version: 'V00311', titulo: 'Corregido el error al abrir en pestaña nueva tras publicar', resumen: 'Se corrigió el error que a veces salía al abrir "Ver en nueva pestaña" justo después de publicarse una actualización.' },
];
